{"file_path": "/home/nahom/Desktop/Others/EaglePointAI/vibe-coding-projects/week-2/SilverOak/TASK-17/repo/crates/infrastructure/src/seed.rs", "content": "use anyhow::Result;
use sqlx::PgPool;

/// Idempotent baseline seed.
///
/// Phase 1 only seeds the canonical role catalog so later phases can
/// reference it. All inserts use ON CONFLICT DO NOTHING so re-running on
/// container restart is safe.
pub async fn run(pool: &PgPool) -> Result<()> {
    tracing::info!("running baseline seed");

    let roles: &[(&str, &str)] = &[
        ("admin", "Administrator"),
        ("approver", "Approver"),
        ("requester", "Requester"),
        ("inventory_manager", "Inventory Manager"),
        ("family", "Family Portal"),
        ("analyst", "Analyst"),
    ];

    for (key, label) in roles {
        sqlx::query(
            "INSERT INTO roles (id, key, label) VALUES (gen_random_uuid(), $1, $2)
             ON CONFLICT (key) DO NOTHING",
        )
        .bind(key)
        .bind(label)
        .execute(pool)
        .await?;
    }

    tracing::info!("baseline seed complete");
    Ok(())
}
"}

