use shared::ApiError;
use thiserror::Error;

#[derive(Debug, Error)]
pub enum ApiAppError {
    #[error("not found")]
    NotFound,
    #[error("bad request: {0}")]
    BadRequest(String),
    #[error("internal: {0}")]
    Internal(String),
}

impl ResponseError for ApiAppError {
    fn status_code(&self) -> StatusCode {
        match self {
            Self::NotFound => StatusCode::NOT_FOUND,
            Self::BadRequest(_) => StatusCode::BAD_REQUEST,
            Self::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }

    fn error_response(&self) -> HttpResponse {
        let (code, message) = match self {
            Self::NotFound => ("not_found".to_string(), self.to_string()),
            Self::BadRequest(m) => ("bad_request".to_string(), m.clone()),
            Self::Internal(m) => ("internal".to_string(), m.clone()),
        };
        HttpResponse::build(self.status_code()).json(ApiError { code, message })
    }
}
"}

