use async_trait_stub::async_trait;
use sqlx::PgPool;

// Phase 1 declares the job trait and a registry. Concrete jobs (nightly
// re-orders, snapshot rollups, family-portal digests) arrive in later
// phases — each will live in its own file under this module.
pub mod async_trait_stub {
    pub use std::future::Future;
    // Re-export the real macro to keep call sites idiomatic.
    pub use async_trait::async_trait;
}

#[async_trait]
pub trait Job: Send + Sync {
    fn name(&self) -> &'static str;
    async fn maybe_run(&self, pool: &PgPool) -> Result<()>;
}

pub struct JobRegistry {
    jobs: Vec<Box<dyn Job>>,
}

impl JobRegistry {
    pub fn iter(&self) -> impl Iterator<Item = &dyn Job> {
        self.jobs.iter().map(|b| b.as_ref())
    }
}

pub fn register() -> JobRegistry {
    // Intentionally empty in Phase 1. Adding a job means pushing into this
    // vec — no other wiring required.
    JobRegistry { jobs: Vec::new() }
}
"}

