:root {
  --color-bg: #f6f7f9;
  --color-surface: #ffffff;
  --color-surface-alt: #f0f2f6;
  --color-border: #e3e6ec;
  --color-text: #1a1f2b;
  --color-text-muted: #5b6478;
  --color-primary: #1f6f54;
  --color-primary-hover: #185a44;
  --color-accent: #c9a24a;
  --color-danger: #b3261e;
  --color-warning: #b9750f;
  --color-success: #1f6f54;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 2px rgba(20, 30, 50, 0.06);
  --shadow-md: 0 4px 16px rgba(20, 30, 50, 0.08);
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-8: 48px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; font-family: var(--font-sans); color: var(--color-text); background: var(--color-bg); }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; }

/* Layout shell */
.app-shell { display: grid; grid-template-columns: 260px 1fr; min-height: 100vh; }
@media (max-width: 900px) { .app-shell { grid-template-columns: 1fr; } }

.sidebar {
  background: var(--color-surface);
  border-right: 1px solid var(--color-border);
  padding: var(--space-5) var(--space-4);
  display: flex; flex-direction: column; gap: var(--space-4);
}
.sidebar .brand { font-weight: 700; font-size: 18px; letter-spacing: 0.2px; }
.sidebar .brand small { display: block; color: var(--color-text-muted); font-weight: 500; font-size: 12px; }
.nav-section { font-size: 11px; text-transform: uppercase; letter-spacing: 0.6px; color: var(--color-text-muted); margin-top: var(--space-3); }
.nav-link {
  display: block; padding: 10px 12px; border-radius: var(--radius-sm);
  color: var(--color-text); font-size: 14px;
}
.nav-link:hover { background: var(--color-surface-alt); }
.nav-link.active { background: var(--color-primary); color: white; }

.main { display: flex; flex-direction: column; min-width: 0; }
.topbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: var(--space-4) var(--space-6);
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}
.topbar h1 { margin: 0; font-size: 18px; font-weight: 600; }
.content { padding: var(--space-6); }

/* Primitives */
.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-5);
  box-shadow: var(--shadow-sm);
}
.card + .card { margin-top: var(--space-4); }
.card h2 { margin: 0 0 var(--space-3); font-size: 16px; }
.card .muted { color: var(--color-text-muted); font-size: 14px; }

.button {
  display: inline-flex; align-items: center; gap: var(--space-2);
  padding: 10px 16px; border-radius: var(--radius-sm);
  background: var(--color-primary); color: white; border: none; cursor: pointer;
  font-size: 14px; font-weight: 500;
}
.button:hover { background: var(--color-primary-hover); }
.button.secondary { background: var(--color-surface-alt); color: var(--color-text); }

.table { width: 100%; border-collapse: collapse; font-size: 14px; }
.table th, .table td { padding: 10px 12px; text-align: left; border-bottom: 1px solid var(--color-border); }
.table th { color: var(--color-text-muted); font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: 0.4px; }

.form-field { display: flex; flex-direction: column; gap: 6px; margin-bottom: var(--space-4); }
.form-field label { font-size: 13px; color: var(--color-text-muted); }
.form-field input, .form-field select, .form-field textarea {
  padding: 10px 12px; border: 1px solid var(--color-border); border-radius: var(--radius-sm);
  background: var(--color-surface); font-size: 14px; font-family: inherit;
}

.state {
  border: 1px dashed var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-6);
  text-align: center;
  color: var(--color-text-muted);
}
.state.error { border-color: var(--color-danger); color: var(--color-danger); }

.page-header { margin-bottom: var(--space-5); }
.page-header h1 { margin: 0 0 var(--space-2); font-size: 24px; }
.page-header p { margin: 0; color: var(--color-text-muted); }

.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-4); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-4); }
@media (max-width: 900px) { .grid-2, .grid-3 { grid-template-columns: 1fr; } }

.stat { display: flex; flex-direction: column; gap: 4px; }
.stat .value { font-size: 28px; font-weight: 600; }
.stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.4px; color: var(--color-text-muted); }

/* Login */
.auth-shell { min-height: 100vh; display: grid; place-items: center; background: var(--color-bg); }
.auth-card { width: 100%; max-width: 380px; }
"}

