{"file_path": "/home/nahom/Desktop/Others/EaglePointAI/vibe-coding-projects/week-2/SilverOak/TASK-17/repo/apps/backend-api/src/security/rate_limit.rs", "content": "use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use std::time::{Duration, Instant};

use parking_lot::Mutex;

use super::constants::RATE_LIMIT_PER_MIN;

/// Per-IP sliding-window rate limiter, in-process.
///
/// Limitation (documented in README): in a multi-replica deployment each
/// API container enforces its own window. The Task Prompt's offline-first
/// brief favors a single API container so this trade-off is acceptable;
/// upgrading to a shared store is a clean swap behind this struct.
#[derive(Clone)]
pub struct RateLimiter {
    inner: Arc<Mutex<HashMap<String, VecDeque<Instant>>>>,
    window: Duration,
    limit: usize,
}

impl Default for RateLimiter {
    fn default() -> Self {
        Self {
            inner: Arc::new(Mutex::new(HashMap::new())),
            window: Duration::from_secs(60),
            limit: RATE_LIMIT_PER_MIN as usize,
        }
    }
}

impl RateLimiter {
    /// Returns Ok(()) if the request is allowed, Err(retry_after_seconds)
    /// if it is rejected.
    pub fn check(&self, ip: &str) -> Result<(), u64> {
        let now = Instant::now();
        let mut map = self.inner.lock();
        let entry = map.entry(ip.to_string()).or_default();
        while let Some(front) = entry.front() {
            if now.duration_since(*front) > self.window {
                entry.pop_front();
            } else {
                break;
            }
        }
        if entry.len() >= self.limit {
            let oldest = *entry.front().expect("non-empty");
            let elapsed = now.duration_since(oldest);
            let retry = self.window.saturating_sub(elapsed).as_secs().max(1);
            return Err(retry);
        }
        entry.push_back(now);
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn allows_up_to_limit_then_rejects() {
        let rl = RateLimiter::default();
        for _ in 0..RATE_LIMIT_PER_MIN {
            assert!(rl.check("1.2.3.4").is_ok());
        }
        assert!(rl.check("1.2.3.4").is_err());
        // different IP not affected
        assert!(rl.check("9.9.9.9").is_ok());
    }
}
"}

