//! request. Order on the API scope is significant:
//!
//!   1. `IpGuard`        — blacklist + per-IP rate limit
//!   2. `SignedAuth`     — token + signature + replay window
//!   3. handler          — receives a `Principal` extension
//!
//! Routes that should be public (login, health, recovery request) live
//! OUTSIDE the `SignedAuth` scope so the gating is statically obvious in
//! `routes/mod.rs`.

use std::future::{ready, Ready};
use std::rc::Rc;

use actix_web::{
    body::{BoxBody, EitherBody, MessageBody},
    dev::{Service, ServiceRequest, ServiceResponse, Transform},
    web, Error, HttpMessage, HttpResponse,
};
use futures_util::future::LocalBoxFuture;
use sqlx::PgPool;

use super::{
    blacklist, constants::*, rate_limit::RateLimiter, rbac, signing, tokens::ApiTokenService,
};
use crate::error::ApiAppError;

// ----------------- IpGuard -----------------
pub struct IpGuard {
    pub limiter: RateLimiter,
}

impl<S, B> Transform<S, ServiceRequest> for IpGuard
where
    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
    B: MessageBody + 'static,
{
    type Response = ServiceResponse<EitherBody<B, BoxBody>>;
    type Error = Error;
    type InitError = ();
    type Transform = IpGuardMw<S>;
    type Future = Ready<Result<Self::Transform, Self::InitError>>;

    fn new_transform(&self, service: S) -> Self::Future {
        ready(Ok(IpGuardMw {
            service: Rc::new(service),
            limiter: self.limiter.clone(),
        }))
    }
}

pub struct IpGuardMw<S> {
    service: Rc<S>,
    limiter: RateLimiter,
}

fn client_ip(req: &ServiceRequest) -> String {
    if let Some(h) = req.headers().get("x-forwarded-for") {
        if let Ok(v) = h.to_str() {
            if let Some(first) = v.split(',').next() {
                return first.trim().to_string();
            }
        }
    }
    req.connection_info().realip_remote_addr().unwrap_or("unknown").to_string()
}

impl<S, B> Service<ServiceRequest> for IpGuardMw<S>
where
    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
    B: MessageBody + 'static,
{
    type Response = ServiceResponse<EitherBody<B, BoxBody>>;
    type Error = Error;
    type Future = LocalBoxFuture<'static, Result<Self::Response, Self::Error>>;

    fn poll_ready(&self, cx: &mut std::task::Context<'_>) -> std::task::Poll<Result<(), Self::Error>> {
        self.service.poll_ready(cx)
    }

    fn call(&self, req: ServiceRequest) -> Self::Future {
        let svc = self.service.clone();
        let limiter = self.limiter.clone();
        Box::pin(async move {
            let ip = client_ip(&req);
            req.extensions_mut().insert(ClientIp(ip.clone()));

            let pool = req.app_data::<web::Data<PgPool>>().cloned();
            if let Some(pool) = pool {
                if blacklist::is_blacklisted(pool.get_ref(), &ip).await.unwrap_or(false) {
                    let resp = ApiAppError::Forbidden("ip blacklisted".into()).error_response();
                    return Ok(req.into_response(resp).map_into_right_body());
                }
            }
            if let Err(retry) = limiter.check(&ip) {
                let resp = ApiAppError::RateLimited(retry).error_response();
                return Ok(req.into_response(resp).map_into_right_body());
            }
            svc.call(req).await.map(|r| r.map_into_left_body())
        })
    }
}

#[derive(Clone)]
pub struct ClientIp(pub String);

// ----------------- SignedAuth -----------------
pub struct SignedAuth;

impl<S, B> Transform<S, ServiceRequest> for SignedAuth
where
    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
    B: MessageBody + 'static,
{
    type Response = ServiceResponse<EitherBody<B, BoxBody>>;
    type Error = Error;
    type InitError = ();
    type Transform = SignedAuthMw<S>;
    type Future = Ready<Result<Self::Transform, Self::InitError>>;

    fn new_transform(&self, service: S) -> Self::Future {
        ready(Ok(SignedAuthMw { service: Rc::new(service) }))
    }
}

pub struct SignedAuthMw<S> { service: Rc<S> }

fn header<'a>(req: &'a ServiceRequest, name: &str) -> Option<&'a str> {
    req.headers().get(name).and_then(|h| h.to_str().ok())
}

impl<S, B> Service<ServiceRequest> for SignedAuthMw<S>
where
    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
    B: MessageBody + 'static,
{
    type Response = ServiceResponse<EitherBody<B, BoxBody>>;
    type Error = Error;
    type Future = LocalBoxFuture<'static, Result<Self::Response, Self::Error>>;

    fn poll_ready(&self, cx: &mut std::task::Context<'_>) -> std::task::Poll<Result<(), Self::Error>> {
        self.service.poll_ready(cx)
    }

    fn call(&self, req: ServiceRequest) -> Self::Future {
        let svc = self.service.clone();
        Box::pin(async move {
            let reject = |err: ApiAppError, req: ServiceRequest| -> ServiceResponse<EitherBody<B, BoxBody>> {
                req.into_response(err.error_response()).map_into_right_body()
            };

            let token = match header(&req, HDR_API_TOKEN) {
                Some(t) => t.to_string(),
                None => return Ok(reject(ApiAppError::Unauthorized("missing api token".into()), req)),
            };
            let ts = match header(&req, HDR_TIMESTAMP) {
                Some(t) => t.to_string(),
                None => return Ok(reject(ApiAppError::Unauthorized("missing timestamp".into()), req)),
            };
            let nonce = match header(&req, HDR_NONCE) {
                Some(t) => t.to_string(),
                None => return Ok(reject(ApiAppError::Unauthorized("missing nonce".into()), req)),
            };
            let sig = match header(&req, HDR_SIGNATURE) {
                Some(t) => t.to_string(),
                None => return Ok(reject(ApiAppError::Unauthorized("missing signature".into()), req)),
            };

            let ts_parsed = match signing::parse_timestamp(&ts) {
                Ok(v) => v,
                Err(e) => return Ok(reject(e, req)),
            };
            if !signing::within_replay_window(ts_parsed) {
                return Ok(reject(ApiAppError::Unauthorized("timestamp outside replay window".into()), req));
            }

            let pool = req
                .app_data::<web::Data<PgPool>>()
                .cloned()
                .expect("pg pool present");

            let ctx = match ApiTokenService::lookup(pool.get_ref(), &token).await {
                Ok(Some(c)) => c,
                Ok(None) => return Ok(reject(ApiAppError::Unauthorized("invalid or expired token".into()), req)),
                Err(e) => return Ok(reject(ApiAppError::Internal(e.to_string()), req)),
            };

            // Read body, then verify signature, then re-attach body for handler.
            let (http_req, payload) = req.into_parts();
            let body_bytes = match actix_web::web::Bytes::from_request(&http_req, &mut actix_web::dev::Payload::from(payload)).await {
                Ok(b) => b,
                Err(_) => {
                    let req = ServiceRequest::from_request(http_req);
                    return Ok(reject(ApiAppError::BadRequest("could not read body".into()), req));
                }
            };

            let canonical = signing::RequestSigner::canonical_string(
                http_req.method().as_str(),
                http_req.uri().path(),
                &ts,
                &nonce,
                &body_bytes,
            );
            if !signing::RequestSigner::verify(&ctx.signing_key, &canonical, &sig) {
                let req = ServiceRequest::from_parts(http_req, dev_payload_from_bytes(body_bytes));
                return Ok(reject(ApiAppError::Unauthorized("bad signature".into()), req));
            }

            if let Err(e) = signing::record_signature(pool.get_ref(), ctx.user_id, &sig).await {
                let req = ServiceRequest::from_parts(http_req, dev_payload_from_bytes(body_bytes));
                return Ok(reject(e, req));
            }

            let principal = match rbac::load_principal(pool.get_ref(), ctx.user_id).await {
                Ok(p) => p,
                Err(e) => {
                    let req = ServiceRequest::from_parts(http_req, dev_payload_from_bytes(body_bytes));
                    return Ok(reject(ApiAppError::Internal(e.to_string()), req));
                }
            };

            let mut req = ServiceRequest::from_parts(http_req, dev_payload_from_bytes(body_bytes));
            req.extensions_mut().insert(principal);
            svc.call(req).await.map(|r| r.map_into_left_body())
        })
    }
}

fn dev_payload_from_bytes(bytes: actix_web::web::Bytes) -> actix_web::dev::Payload {
    use futures_util::stream;
    let stream = stream::once(async move { Ok::<_, actix_web::error::PayloadError>(bytes) });
    actix_web::dev::Payload::from(Box::pin(stream) as std::pin::Pin<Box<dyn futures_util::Stream<Item = Result<_, _>>>>)
}

// Need FromRequest in scope for Bytes
use actix_web::FromRequest;
"}

