    }

    fn call(&self, req: ServiceRequest) -> Self::Future {
        let svc = self.service.clone();
        Box::pin(async move {
            let reject = |err: ApiAppError, req: ServiceRequest| -> ServiceResponse<EitherBody<B, BoxBody>> {
