        Some(p.user_id),
        Some(body.user_id),
        "grant_role",
        serde_json::json!({"role_key": body.role_key}),
    )
    .await?;
    Ok(HttpResponse::Ok().json(serde_json::json!({"ok": true})))
}

// ---- representative scoped endpoint: list department residents (stub) ----
#[get("/departments/{dept_id}/residents")]
pub async fn list_department_residents(
    path: web::Path<String>,
    req: HttpRequest,
) -> Result<HttpResponse, ApiAppError> {
    let p = principal(&req)?;
    p.require("residents:read")?;
    p.require_scope(ScopeKind::Department, &path)?;
    // Phase 2: this endpoint exists to prove scope enforcement end-to-end.
    // The real resident model lands in a later phase.
    Ok(HttpResponse::Ok().json(serde_json::json!({
        "department_id": path.into_inner(),
        "residents": []
    })))
}

#[get("/me")]
pub async fn me(req: HttpRequest) -> Result<HttpResponse, ApiAppError> {
    let p = principal(&req)?;
    Ok(HttpResponse::Ok().json(p))
}
