use gloo::net::http::{Request, Response};
use hmac::{Hmac, Mac};
use sha2::Sha256;
use uuid::Uuid;

type HmacSha256 = Hmac<Sha256>;

/// Browser-side signed-request client. Mirrors `security::signing` on the
/// server: METHOD\nPATH\nTIMESTAMP\nNONCE, HMAC-SHA256 with the per-token
/// signing key.
pub struct ApiClient {
    pub api_token: String,
    pub signing_key: String,
}

fn sign(key: &str, canonical: &str) -> String {
    let mut mac = HmacSha256::new_from_slice(key.as_bytes()).expect("hmac");
    mac.update(canonical.as_bytes());
    hex::encode(mac.finalize().into_bytes())
}

impl ApiClient {
    pub async fn get(&self, path: &str) -> Result<Response, String> {
        let ts = Utc::now().timestamp().to_string();
        let nonce = Uuid::new_v4().to_string();
        let canonical = format!("GET\n{}\n{}\n{}", path, ts, nonce);
        let sig = sign(&self.signing_key, &canonical);
        Request::get(path)
            .header("x-silveroak-token", &self.api_token)
            .header("x-silveroak-timestamp", &ts)
            .header("x-silveroak-nonce", &nonce)
            .header("x-silveroak-signature", &sig)
            .send()
            .await
            .map_err(|e| e.to_string())
    }
}
"}

