//! DB-bound flows (login, lockout, replay store, scope queries) live in
//! the bash suite under `API_tests/` so a reviewer can see them exercised
//! against the actual Postgres-backed stack.

use chrono::{Duration, Utc};

// Re-import the modules under test by including the source paths.
// We use a small `mod` shim because backend-api is a binary crate.
#[path = "../src/security/constants.rs"] mod constants;
#[path = "../src/security/signing.rs"]   mod signing;
#[path = "../src/security/rate_limit.rs"] mod rate_limit;
#[path = "../src/error.rs"] mod error;

#[test]
fn signature_round_trip_and_tamper() {
    let canon = signing::RequestSigner::canonical_string_no_body(
        "GET", "/api/v1/me", "1700000000", "nonce-1",
    );
    let sig = signing::RequestSigner::sign("k", &canon);
    assert!(signing::RequestSigner::verify("k", &canon, &sig));
    assert!(!signing::RequestSigner::verify("k2", &canon, &sig));
    let tampered = signing::RequestSigner::canonical_string_no_body(
        "POST", "/api/v1/me", "1700000000", "nonce-1",
    );
    assert!(!signing::RequestSigner::verify("k", &tampered, &sig));
}

#[test]
fn replay_window_enforced() {
    let now = Utc::now();
    assert!(signing::within_replay_window(now));
    assert!(signing::within_replay_window(now - Duration::seconds(60)));
    assert!(!signing::within_replay_window(now - Duration::seconds(61)));
    assert!(!signing::within_replay_window(now + Duration::seconds(120)));
}

#[test]
fn rate_limit_blocks_at_120() {
    let rl = rate_limit::RateLimiter::default();
    for _ in 0..constants::RATE_LIMIT_PER_MIN {
        assert!(rl.check("10.0.0.1").is_ok());
    }
    assert!(rl.check("10.0.0.1").is_err());
}
"}

