208	pub async fn submit(
209	    pool: &PgPool,
210	    p: &Principal,
211	    req_id: Uuid,
212	) -> Result<RequisitionDetail, ApiAppError> {
213	    p.require("requisitions:write")?;
214	    let row: Option<(Uuid, String, i64, bool)> = sqlx::query_as(
215	        "SELECT requester_id, status, total_amount_cents, contains_controlled
216	         FROM requisitions WHERE id = $1",
217	    )
218	    .bind(req_id).fetch_optional(pool).await?;
219	    let (requester, status, total, ctrl) = row.ok_or(ApiAppError::NotFound)?;
220	    assert_owner(p, requester)?;
221	    let cur = ReqStatus::parse(&status).unwrap();
222	    Transition::check(cur, ReqStatus::PendingApproval)?;
223	
224	    let workflow_id = load_workflow_id(pool).await?;
225	    let snap = ReqSnapshot { total_amount_cents: total, contains_controlled: ctrl };
226	    let route: Vec<ResolvedNode> = resolve_route(pool, workflow_id, &snap).await?;
227	
228	    let mut tx = pool.begin().await?;
229	    sqlx::query("UPDATE requisitions SET status='pending_approval', workflow_id=$2, submitted_at=NOW(), updated_at=NOW() WHERE id=$1")
230	        .bind(req_id).bind(workflow_id).execute(&mut *tx).await?;
231	    let inst: (Uuid,) = sqlx::query_as(
232	        "INSERT INTO requisition_approval_instances (requisition_id, workflow_id) VALUES ($1,$2) RETURNING id",
233	    ).bind(req_id).bind(workflow_id).fetch_one(&mut *tx).await?;
234	    for (i, n) in route.iter().enumerate() {
235	        sqlx::query(
236	            "INSERT INTO requisition_approval_steps (instance_id, sequence, node_id, required_role)
237	             VALUES ($1, $2, $3, $4)",
238	        )
239	        .bind(inst.0).bind(i as i32 + 1).bind(n.node_id).bind(&n.required_role)
240	        .execute(&mut *tx).await?;
241	    }
242	    audit(&mut tx, req_id, Some(p.user_id), "submitted",
243	          Some(&format!("routed to {} approval node(s)", route.len()))).await?;
244	    tx.commit().await?;
245	    load_detail(pool, p, req_id).await
246	}
