275	async fn current_pending_step(
276	    pool: &PgPool,
277	    req_id: Uuid,
278	) -> Result<(Uuid, Uuid, i32, String), ApiAppError> {
279	    // (instance_id, step_id, sequence, required_role) for the next undecided step
280	    let row: Option<(Uuid, Uuid, i32, String)> = sqlx::query_as(
281	        "SELECT s.instance_id, s.id, s.sequence, s.required_role
282	         FROM requisition_approval_steps s
283	         JOIN requisition_approval_instances i ON i.id = s.instance_id
284	         WHERE i.requisition_id = $1 AND i.status='in_progress' AND s.decision IS NULL
285	         ORDER BY s.sequence LIMIT 1",
286	    )
287	    .bind(req_id).fetch_optional(pool).await?;
288	    row.ok_or_else(|| ApiAppError::BadRequest("no pending approval step".into()))
289	}
