291	fn assert_can_act_at_step(p: &Principal, required_role: &str) -> Result<(), ApiAppError> {
292	    if p.has_role(required_role) || p.permissions.contains("*") {
293	        Ok(())
294	    } else {
295	        Err(ApiAppError::Forbidden(format!("requires role {required_role}")))
296	    }
297	}
