299	pub async fn approve(
300	    pool: &PgPool,
301	    p: &Principal,
302	    req_id: Uuid,
303	    input: DecisionInput,
304	) -> Result<RequisitionDetail, ApiAppError> {
305	    p.require("requisitions:approve")?;
306	    let (instance_id, step_id, sequence, role) = current_pending_step(pool, req_id).await?;
307	    assert_can_act_at_step(p, &role)?;
308	
309	    // Determine if this is the LAST step.
310	    let total_steps: (i64,) =
311	        sqlx::query_as("SELECT COUNT(*) FROM requisition_approval_steps WHERE instance_id=$1")
312	            .bind(instance_id).fetch_one(pool).await?;
313	    let is_final = sequence as i64 == total_steps.0;
314	
315	    if !is_final {
316	        // Just record the step decision; status stays pending_approval.
317	        let mut tx = pool.begin().await?;
318	        sqlx::query(
319	            "UPDATE requisition_approval_steps SET decision='approved', decided_by=$2, decided_at=NOW(), reason=$3 WHERE id=$1",
320	        )
321	        .bind(step_id).bind(p.user_id).bind(input.comment.as_deref())
322	        .execute(&mut *tx).await?;
323	        sqlx::query("UPDATE requisition_approval_instances SET current_step=$2 WHERE id=$1")
324	            .bind(instance_id).bind(sequence).execute(&mut *tx).await?;
325	        audit(&mut tx, req_id, Some(p.user_id), "approved_step",
326	              input.comment.as_deref()).await?;
327	        tx.commit().await?;
328	        return load_detail(pool, p, req_id).await;
329	    }
330	
331	    // FINAL APPROVAL — the high-risk path.
332	    finalize_in_transaction(pool, p, req_id, instance_id, step_id, input.comment.as_deref()).await?;
333	    load_detail(pool, p, req_id).await
334	}
