336	/// Single transaction: mark final step approved, mark instance approved,
337	/// move requisition through approved_final → issued, verify stock, deduct
338	/// stock per line, create issue_record + issue_record_lines, append audit.
339	/// Any failure rolls back the entire chain.
340	async fn finalize_in_transaction(
341	    pool: &PgPool,
342	    p: &Principal,
343	    req_id: Uuid,
344	    instance_id: Uuid,
345	    step_id: Uuid,
346	    comment: Option<&str>,
347	) -> Result<(), ApiAppError> {
348	    let mut tx = pool.begin().await?;
349	
350	    // Lock the requisition + its lines.
351	    let req: (String, Uuid) = sqlx::query_as(
352	        "SELECT status, site_id FROM requisitions WHERE id=$1 FOR UPDATE",
353	    ).bind(req_id).fetch_one(&mut *tx).await?;
354	    let cur = ReqStatus::parse(&req.0).unwrap();
355	    Transition::check(cur, ReqStatus::ApprovedFinal)?;
356	    let site_id = req.1;
357	
358	    // Lock + read lines.
359	    let lines: Vec<(Uuid, Uuid, i32, i64, i64)> = sqlx::query_as(
360	        "SELECT id, item_id, quantity, unit_price_cents, line_total_cents
361	         FROM requisition_lines WHERE requisition_id=$1 ORDER BY id",
362	    ).bind(req_id).fetch_all(&mut *tx).await?;
363	
364	    // Verify + deduct stock per line, locking the stock row.
365	    for (_lid, item_id, qty, _, _) in &lines {
366	        let stock: Option<(i32,)> = sqlx::query_as(
367	            "SELECT on_hand FROM inventory_stock_by_site WHERE item_id=$1 AND site_id=$2 FOR UPDATE",
368	        ).bind(item_id).bind(site_id).fetch_optional(&mut *tx).await?;
369	        let on_hand = stock.map(|s| s.0).unwrap_or(0);
370	        if on_hand < *qty {
371	            // Rolls back the whole transaction by returning early.
372	            return Err(ApiAppError::BadRequest(format!(
373	                "insufficient stock for item {item_id}: have {on_hand}, need {qty}"
374	            )));
375	        }
376	        sqlx::query(
377	            "UPDATE inventory_stock_by_site SET on_hand = on_hand - $3 WHERE item_id=$1 AND site_id=$2",
378	        ).bind(item_id).bind(site_id).bind(qty).execute(&mut *tx).await?;
379	    }
380	
381	    // Mark approval step + instance.
382	    sqlx::query(
383	        "UPDATE requisition_approval_steps SET decision='approved', decided_by=$2, decided_at=NOW(), reason=$3 WHERE id=$1",
384	    ).bind(step_id).bind(p.user_id).bind(comment).execute(&mut *tx).await?;
385	    sqlx::query("UPDATE requisition_approval_instances SET status='approved' WHERE id=$1")
386	        .bind(instance_id).execute(&mut *tx).await?;
387	
388	    // approved_final → issued (record both transitions in audit).
389	    sqlx::query("UPDATE requisitions SET status='approved_final', finalized_at=NOW(), updated_at=NOW() WHERE id=$1")
390	        .bind(req_id).execute(&mut *tx).await?;
391	    audit(&mut tx, req_id, Some(p.user_id), "approved_final", comment).await?;
392	
393	    sqlx::query("UPDATE requisitions SET status='issued', updated_at=NOW() WHERE id=$1")
394	        .bind(req_id).execute(&mut *tx).await?;
395	
396	    // Issue record + lines.
397	    let issue: (Uuid,) = sqlx::query_as(
398	        "INSERT INTO issue_records (requisition_id, site_id, issued_by) VALUES ($1,$2,$3) RETURNING id",
399	    ).bind(req_id).bind(site_id).bind(p.user_id).fetch_one(&mut *tx).await?;
400	    for (_lid, item_id, qty, unit_price, line_total) in &lines {
401	        sqlx::query(
402	            "INSERT INTO issue_record_lines (issue_record_id, item_id, quantity, unit_price_cents, line_total_cents)
403	             VALUES ($1,$2,$3,$4,$5)",
404	        ).bind(issue.0).bind(item_id).bind(qty).bind(unit_price).bind(line_total)
405	        .execute(&mut *tx).await?;
406	    }
407	    audit(&mut tx, req_id, Some(p.user_id), "issued",
408	          Some(&format!("issue_record={}", issue.0))).await?;
409	
410	    tx.commit().await?;
411	    Ok(())
412	}
