441	        .bind(instance_id).execute(&mut *tx).await?;
442	    sqlx::query("UPDATE requisitions SET status='rejected', updated_at=NOW() WHERE id=$1")
443	        .bind(req_id).execute(&mut *tx).await?;
444	    audit(&mut tx, req_id, Some(p.user_id), "rejected", Some(&reason)).await?;
445	    tx.commit().await?;
446	    load_detail(pool, p, req_id).await
447	}
