495	pub async fn approver_inbox(pool: &PgPool, p: &Principal) -> Result<Vec<RequisitionDetail>, ApiAppError> {
496	    p.require("requisitions:approve")?;
497	    // Find all requisitions whose next undecided step requires a role the
498	    // principal holds, AND whose department is in their scope (unless they
499	    // hold scope:any).
500	    let scope_any = p.permissions.contains("scope:any");
501	    let dept_refs: Vec<String> = p.scopes.iter()
502	        .filter(|s| s.kind == ScopeKind::Department)
503	        .map(|s| s.reference.clone()).collect();
504	
505	    let rows: Vec<(Uuid,)> = sqlx::query_as(
506	        "SELECT DISTINCT r.id
507	         FROM requisitions r
508	         JOIN requisition_approval_instances i ON i.requisition_id = r.id
509	         JOIN requisition_approval_steps s ON s.instance_id = i.id
510	         WHERE r.status='pending_approval'
511	           AND i.status='in_progress'
512	           AND s.decision IS NULL
513	           AND s.sequence = (
514	               SELECT MIN(s2.sequence) FROM requisition_approval_steps s2
515	               WHERE s2.instance_id = i.id AND s2.decision IS NULL
516	           )
517	           AND s.required_role = ANY($1)
518	           AND ($2::bool OR r.department_id::text = ANY($3))
519	         ORDER BY r.id",
520	    )
521	    .bind(&p.roles)
522	    .bind(scope_any)
523	    .bind(&dept_refs)
524	    .fetch_all(pool).await?;
525	
526	    let mut out = Vec::new();
527	    for (id,) in rows { out.push(load_detail(pool, p, id).await?); }
528	    Ok(out)
529	}
