531	pub async fn load_detail(pool: &PgPool, p: &Principal, req_id: Uuid) -> Result<RequisitionDetail, ApiAppError> {
532	    let req: Option<(Uuid, String, String, Uuid, String, Uuid, Uuid, NaiveDate, String, i64, bool, Option<Uuid>)> =
533	        sqlx::query_as(
534	            "SELECT r.id, r.ref_code, r.status, r.requester_id, u.email,
535	                    r.site_id, r.department_id, r.needed_by, r.justification,
536	                    r.total_amount_cents, r.contains_controlled, r.workflow_id
537	             FROM requisitions r JOIN users u ON u.id = r.requester_id
538	             WHERE r.id = $1",
539	        ).bind(req_id).fetch_optional(pool).await?;
540	    let r = req.ok_or(ApiAppError::NotFound)?;
541	
542	    // Object-level read auth: requester themselves, an approver who holds
543	    // an approve permission and matching role/scope, or scope:any.
544	    let scope_any = p.permissions.contains("scope:any");
545	    let owner = p.user_id == r.3;
546	    let approver = p.permissions.contains("requisitions:approve");
547	    let dept_ok = scope_any
548	        || p.scopes.iter().any(|s| s.kind == ScopeKind::Department && s.reference == r.6.to_string());
549	    if !(owner || (approver && dept_ok) || scope_any) {
550	        return Err(ApiAppError::Forbidden("not authorized to view this requisition".into()));
551	    }
552	
553	    let lines: Vec<(Uuid, Uuid, String, String, i32, i64, i64, bool, Option<i32>)> = sqlx::query_as(
554	        "SELECT rl.id, rl.item_id, i.name, i.sku, rl.quantity, rl.unit_price_cents, rl.line_total_cents,
555	                c.controlled, st.on_hand
556	         FROM requisition_lines rl
557	         JOIN inventory_items i ON i.id = rl.item_id
558	         JOIN inventory_categories c ON c.id = i.category_id
559	         LEFT JOIN inventory_stock_by_site st ON st.item_id = rl.item_id AND st.site_id = $2
560	         WHERE rl.requisition_id = $1 ORDER BY rl.id",
561	    ).bind(req_id).bind(r.5).fetch_all(pool).await?;
562	
563	    let route: Vec<(i32, String, String, Option<String>, Option<Uuid>, Option<String>)> = sqlx::query_as(
564	        "SELECT s.sequence, n.label, s.required_role, s.decision, s.decided_by, s.reason
565	         FROM requisition_approval_steps s
566	         JOIN approval_nodes n ON n.id = s.node_id
567	         JOIN requisition_approval_instances i ON i.id = s.instance_id
568	         WHERE i.requisition_id = $1 ORDER BY s.sequence",
569	    ).bind(req_id).fetch_all(pool).await?;
570	
571	    let audit_rows: Vec<(chrono::DateTime<chrono::Utc>, Option<Uuid>, String, Option<String>)> = sqlx::query_as(
572	        "SELECT occurred_at, actor_user_id, event_kind, comment FROM requisition_audit
573	         WHERE requisition_id=$1 ORDER BY occurred_at",
574	    ).bind(req_id).fetch_all(pool).await?;
575	
576	    Ok(RequisitionDetail {
577	        id: r.0, ref_code: r.1, status: r.2, requester_id: r.3, requester_email: r.4,
578	        site_id: r.5, department_id: r.6, needed_by: r.7, justification: r.8,
579	        total_amount_cents: r.9, contains_controlled: r.10, workflow_id: r.11,
580	        lines: lines.into_iter().map(|l| RequisitionLine {
581	            id: l.0, item_id: l.1, item_name: l.2, sku: l.3,
582	            quantity: l.4, unit_price_cents: l.5, line_total_cents: l.6,
583	            controlled: l.7, on_hand: l.8.unwrap_or(0),
584	        }).collect(),
585	        route: route.into_iter().map(|s| RouteStep {
