    // ── render ────────────────────────────────────────────────────────────
    let cart_data = (*cart).clone();
    let cart_lines = cart_data.as_ref().map(|c| c.lines.clone()).unwrap_or_default();
    let pricing    = cart_data.as_ref().and_then(|c| c.pricing.clone());
    let has_cross  = cart_data.as_ref().map(|c| c.has_cross_store).unwrap_or(false);
    let sel_dm     = cart_data.as_ref().and_then(|c| c.delivery_method_id.clone());
    let cart_coupon = cart_data.as_ref().and_then(|c| c.coupon_code.clone());

    // Group products by store
    let mut stores: Vec<String> = (*products).iter().map(|p| p.store_key.clone()).collect();
    stores.dedup();
    stores.sort();
    stores.dedup();

    html! {
        <>
            <div class="page-header">
                <h1>{"Shop & Cart"}</h1>
                <p>{"Browse consumable items, manage your cart, and checkout."}</p>
            </div>

            if let Some(e) = (*error).clone() {
                <div class="state error">{ e }</div>
            }

            if has_cross {
                <div class="state" style="background:#fff3cd;padding:12px;margin-bottom:12px;border-radius:6px;">
                    {"Your cart contains items from multiple stores. Each store will be fulfilled separately."}
                </div>
            }

            // ── product catalog ──────────────────────────────────────────
            { for stores.iter().map(|store| {
                let store_products: Vec<&Product> = (*products).iter()
                    .filter(|p| &p.store_key == store).collect();
                html! {
                    <Card title={AttrValue::from(format!("Store: {store}"))}>
                        <table class="table">
                            <thead><tr>
                                <th>{"Item"}</th><th>{"Price"}</th>
                                <th>{"Stock"}</th><th>{"Qty"}</th><th></th>
                            </tr></thead>
                            <tbody>
                            { for store_products.into_iter().map(|p| {
                                let pid = p.id.clone();
                                let pid2 = pid.clone();
                                let qty_val = *qty_inputs.get(&pid).unwrap_or(&1);
                                let qi = qty_inputs.clone();
                                let pid3 = pid.clone();
                                let add_cb = set_qty(pid2.clone());
                                html! {
                                    <tr>
                                        <td>{ &p.name }<br/><small class="muted">{ &p.sku }</small></td>
                                        <td>{ cents(p.base_price_cents) }</td>
                                        <td>{ p.stock }</td>
                                        <td>
                                            <input
                                                type="number" min="0" max="5"
                                                style="width:60px"
                                                value={qty_val.to_string()}
                                                oninput={Callback::from(move |e: InputEvent| {
                                                    let el: web_sys::HtmlInputElement = e.target_unchecked_into();
                                                    if let Ok(v) = el.value().parse::<i32>() {
                                                        let mut m = (*qi).clone();
                                                        m.insert(pid3.clone(), v);
                                                        qi.set(m);
                                                    }
                                                })}
                                            />
                                        </td>
                                        <td>
                                            <button class="button" onclick={add_cb}>{"Add"}</button>
                                        </td>
                                    </tr>
                                }
                            })}
                            </tbody>
                        </table>
                    </Card>
                }
            })}

            // ── cart lines ────────────────────────────────────────────────
            <Card title={AttrValue::from("Your cart")}>
                if cart_lines.is_empty() {
                    <p class="muted">{"Cart is empty — add items above."}</p>
                } else {
                    <table class="table">
                        <thead><tr>
                            <th>{"Item"}</th><th>{"Store"}</th><th>{"Qty"}</th>
                            { if let Some(pr) = &pricing {
                                html! { <><th>{"Unit"}</th><th>{"Line"}</th><th>{"Badges"}</th></> }
                            } else { html!{} } }
                            <th></th>
                        </tr></thead>
                        <tbody>
                        { for cart_lines.iter().map(|l| {
                            let pid = l.product_id.clone();
                            let priced = pricing.as_ref().and_then(|pr|
                                pr.lines.iter().find(|pl| pl.product_id == pid).cloned()
                            );
                            let rem = remove_line(pid);
                            html! {
                                <tr>
                                    <td>{ &l.name }<br/><small class="muted">{ &l.sku }</small></td>
                                    <td>{ &l.store_key }</td>
                                    <td>{ l.quantity }</td>
                                    { if let Some(pr) = priced {
                                        html! {
                                            <>
                                                <td>{ cents(pr.unit_price_cents) }</td>
                                                <td>{ cents(pr.line_total_cents) }</td>
                                                <td>
                                                    { if pr.member_price_applied { html!{ <span class="badge">{"member"}</span> } } else { html!{} } }
                                                    { if pr.threshold_discount_applied { html!{ <span class="badge">{"bulk"}</span> } } else { html!{} } }
                                                </td>
                                            </>
                                        }
                                    } else { html!{ <></> } } }
                                    <td><button class="button secondary" onclick={rem}>{"Remove"}</button></td>
                                </tr>
                            }
                        })}
                        </tbody>
                    </table>

                    // Pricing summary
                    if let Some(pr) = &pricing {
                        <div style="margin-top:16px;text-align:right;">
                            <p>{"Subtotal: "}{ cents(pr.subtotal_cents) }</p>
                            if pr.delivery_fee_cents > 0 {
                                <p>{"Delivery: "}{ cents(pr.delivery_fee_cents) }</p>
                            }
                            if pr.coupon_applied {
                                <p style="color:green;">
                                    {"Coupon ("}{pr.coupon_code.as_deref().unwrap_or("")}{"): -"}
                                    { cents(pr.coupon_discount_cents) }
                                </p>
                            }
                            if let Some(reason) = &pr.coupon_blocked_reason {
                                <p style="color:red;">{ format!("Coupon not applied: {reason}") }</p>
                            }
                            <p><strong>{"Total: "}{ cents(pr.total_cents) }</strong></p>
                        </div>

                        // Bundle warnings
                        { for pr.bundle_warnings.iter().map(|w| html! {
                            <div style="background:#fff3cd;padding:8px;margin-top:8px;border-radius:4px;">
                                <strong>{ &w.label }{": "}</strong>{ &w.warning_message }
                            </div>
                        })}

                        // Purchase limit warnings
                        { for pr.purchase_limit_warnings.iter().map(|w| html! {
                            <div style="background:#f8d7da;padding:8px;margin-top:8px;border-radius:4px;">
                                {"Daily limit: "}{ w }
                            </div>
                        })}
                    }
                }
            </Card>

            // ── coupon ────────────────────────────────────────────────────
            <Card title={AttrValue::from("Coupon")}>
                if let Some(ref code) = cart_coupon {
                    <p>{"Applied: "}<strong>{ code }</strong></p>
                } else {
                    <div style="display:flex;gap:8px;align-items:center;">
                        <input
                            type="text"
                            placeholder="Coupon code"
                            value={(*coupon_input).clone()}
                            oninput={{
                                let ci = coupon_input.clone();
                                Callback::from(move |e: InputEvent| {
                                    let el: web_sys::HtmlInputElement = e.target_unchecked_into();
                                    ci.set(el.value());
                                })
                            }}
                        />
                        <button class="button" onclick={apply_coupon_cb}>{"Apply"}</button>
                    </div>
                }
            </Card>

            // ── delivery ──────────────────────────────────────────────────
            <Card title={AttrValue::from("Delivery method")}>
                { for (*methods).iter().map(|m| {
                    let dm_id = m.id.clone();
                    let is_sel = sel_dm.as_deref() == Some(&dm_id);
                    let set_cb = {
                        let dm_id = dm_id.clone();
                        let set_delivery = set_delivery_cb.clone();
                        Callback::from(move |_: MouseEvent| { set_delivery(dm_id.clone()); })
                    };
                    html! {
                        <div style="display:flex;align-items:center;gap:12px;margin-bottom:8px;">
                            <input
                                type="radio"
                                name="delivery"
                                checked={is_sel}
                                onclick={set_cb}
                            />
                            <label>{ format!("{} — {}", m.label, if m.fee_cents==0 { "Free".into() } else { cents(m.fee_cents) }) }</label>
                        </div>
                    }
                })}
            </Card>

            // ── proceed ───────────────────────────────────────────────────
            if !cart_lines.is_empty() {
                <div style="text-align:right;margin-top:16px;">
                    <Link<Route> to={Route::Checkout}>
                        <button class="button">{"Proceed to checkout"}</button>
                    </Link<Route>>
                </div>
            }
        </>
    }
}
"}

