9	/// Materialized authorization context for a request, computed once by the
10	/// auth middleware and read by route handlers via the `Principal` extractor.
11	#[derive(Debug, Clone, Serialize)]
12	pub struct Principal {
13	    pub user_id: Uuid,
14	    pub email: String,
15	    pub roles: Vec<String>,
16	    pub permissions: HashSet<String>,
