20	#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
21	pub struct Scope {
22	    pub kind: ScopeKind,
23	    pub reference: String,
24	}
25	
26	#[derive(Debug, Clone, Copy, Serialize, PartialEq, Eq)]
27	#[serde(rename_all = "snake_case")]
28	pub enum ScopeKind {
29	    Institution,
30	    Site,
31	    Department,
32	    FamilyGroup,
33	}
34	
35	impl ScopeKind {
36	    pub fn as_str(&self) -> &'static str {
37	        match self {
38	            Self::Institution => "institution",
39	            Self::Site => "site",
40	            Self::Department => "department",
41	            Self::FamilyGroup => "family_group",
