55	impl Principal {
56	    pub fn require(&self, permission: &str) -> Result<(), ApiAppError> {
57	        if self.permissions.contains(permission) || self.permissions.contains("*") {
58	            Ok(())
59	        } else {
60	            Err(ApiAppError::Forbidden(format!("missing permission: {permission}")))
61	        }
62	    }
63	
64	    pub fn has_role(&self, role: &str) -> bool {
65	        self.roles.iter().any(|r| r == role)
66	    }
67	
68	    /// Returns Ok if the principal has any scope of the given kind/reference,
69	    /// or holds the wildcard permission `scope:any`.
70	    pub fn require_scope(&self, kind: ScopeKind, reference: &str) -> Result<(), ApiAppError> {
71	        if self.permissions.contains("scope:any") {
72	            return Ok(());
73	        }
74	        let allowed = self.scopes.iter().any(|s| s.kind == kind && s.reference == reference);
75	        if allowed {
76	            Ok(())
77	        } else {
78	            Err(ApiAppError::Forbidden(format!(
79	                "scope denied: {}={}",
80	                kind.as_str(),
81	                reference
82	            )))
83	        }
84	    }
85	}
