               AND (s.student_number ILIKE $2 OR s.first_name ILIKE $2
                    OR s.last_name ILIKE $2 OR COALESCE(s.email,'') ILIKE $2)
             ORDER BY {sort} {dir} LIMIT $3 OFFSET $4",
