// ── error mapping helper ──────────────────────────────────────────────────
fn unique_err(field: &'static str) -> impl Fn(sqlx::Error) -> ApiAppError {
    move |e: sqlx::Error| {
        if let sqlx::Error::Database(db) = &e {
            if db.constraint().is_some() {
                return ApiAppError::BadRequest(format!("{field} already exists"));
            }
        }
