    48	pub fn assert_institution_scope(p: &Principal, institution_id: Uuid) -> Result<(), ApiAppError> {
    49	    if p.permissions.contains("scope:any") { return Ok(()); }
    50	    let ok = p.scopes.iter().any(|s| {
