     1	use chrono::Utc;
     2	use gloo::net::http::{Request, Response};
     3	use hmac::{Hmac, Mac};
     4	use sha2::Sha256;
     5	use uuid::Uuid;
     6	
     7	type HmacSha256 = Hmac<Sha256>;
     8	
     9	/// Browser-side signed-request client. Mirrors `security::signing` on the
    10	/// server: METHOD\nPATH\nTIMESTAMP\nNONCE, HMAC-SHA256 with the per-token
    11	/// signing key.
    12	pub struct ApiClient {
    13	    pub api_token: String,
    14	    pub signing_key: String,
    15	}
    16	
    17	fn sign(key: &str, canonical: &str) -> String {
    18	    let mut mac = HmacSha256::new_from_slice(key.as_bytes()).expect("hmac");
    19	    mac.update(canonical.as_bytes());
    20	    hex::encode(mac.finalize().into_bytes())
    21	}
    22	
    23	impl ApiClient {
    24	    pub async fn get(&self, path: &str) -> Result<Response, String> {
    25	        self.send("GET", path, None::<&str>).await
    26	    }
    27	    pub async fn post_json<S: serde::Serialize>(&self, path: &str, body: &S) -> Result<Response, String> {
    28	        let body = serde_json::to_string(body).map_err(|e| e.to_string())?;
    29	        self.send("POST", path, Some(body.as_str())).await
    30	    }
    31	    async fn send(&self, method: &str, path: &str, body: Option<&str>) -> Result<Response, String> {
    32	        let ts = Utc::now().timestamp().to_string();
    33	        let nonce = Uuid::new_v4().to_string();
    34	        let canonical = format!("{}\n{}\n{}\n{}", method, path, ts, nonce);
    35	        let sig = sign(&self.signing_key, &canonical);
    36	        let builder = match method {
    37	            "POST" => Request::post(path),
    38	            _ => Request::get(path),
    39	        }
    40	        .header("x-silveroak-token", &self.api_token)
    41	        .header("x-silveroak-timestamp", &ts)
    42	        .header("x-silveroak-nonce", &nonce)
    43	        .header("x-silveroak-signature", &sig);
    44	        let res = if let Some(body) = body {
    45	            builder
    46	                .header("content-type", "application/json")
    47	                .body(body.to_string())
    48	                .map_err(|e| e.to_string())?
    49	                .send()
    50	                .await
    51	        } else {
    52	            builder.send().await
    53	        };
    54	        res.map_err(|e| e.to_string())
    55	    }
    56	}
