                        { for EntityTab::all().into_iter().map(|t| {
                            let active = *tab == t;
                            let on_tab = on_tab.clone();
                            html! {
                                <button
                                    class={if active { "button" } else { "button button--ghost" }}
                                    onclick={Callback::from(move |_| on_tab.emit(t))}
                                >
                                    {t.label()}
                                </button>
                            }
                        })}
                    </div>

