                    }

                    // Pagination info
                    <div style="margin-bottom:0.5rem;font-size:0.85rem;color:#666;">
                        {format!("Total: {} record(s)", *total)}
                        {if *total > 20 {
                            format!(" — page {} of {}", *page_num, (*total as f64 / 20.0).ceil() as i64)
                        } else { String::new() }}
                    </div>

                    // Data table
                    { render_table(&data, &make_delete) }

                    // Pagination controls
                    if *total > 20 {
