        EntityTab::Classes => serde_json::json!({
            "code": s("code"),
            "label": s("label"),
            "semester_id": opt_s("semester_id"),
            "department_id": opt_s("department_id"),
            "is_active": true,
        }),
        EntityTab::Courses => serde_json::json!({
            "code": s("code"),
