}

#[derive(Clone, PartialEq, Deserialize, Debug)]
struct DailyStats {
    stat_date: String,
    stats: Vec<StatRow>,
}

#[derive(Clone, PartialEq, Deserialize, Debug)]
struct WeeklyStats {
    week_start: String,
    stats: Vec<StatRow>,
}

