struct DashboardView {
    institution_id: String,
    recent_daily: Vec<DailyStats>,
    recent_weekly: Vec<WeeklyStats>,
    recent_monthly: Vec<MonthlyStats>,
    live: LiveCounts,
}

#[derive(Clone, PartialEq, Deserialize, Debug)]
struct Institution {
    id: String,
    name: String,
    code: String,
}

// ── helpers ────────────────────────────────────────────────────────────────
fn fmt_stat(key: &str) -> &str {
    match key {
        "requisition_count" => "Requisitions",
        "order_count" => "Orders",
        "supply_spend_cents" => "Supply Spend",
        "approved_requisitions" => "Approved Reqs",
        "wellness_sessions" => "Wellness Sessions",
        _ => key,
    }
}

fn fmt_value(key: &str, value: f64) -> String {
    if key == "supply_spend_cents" {
        format!("${:.2}", value / 100.0)
    } else {
        format!("{:.0}", value)
    }
}

// ── component ──────────────────────────────────────────────────────────────
#[function_component(AnalyticsPage)]
pub fn analytics() -> Html {
    let auth = use_auth();
    let institutions = use_state(|| Vec::<Institution>::new());
    let selected_iid = use_state(|| String::new());
    let dashboard = use_state(|| Option::<Result<DashboardView, String>>::None);

    // Load institutions
    {
        let auth = auth.clone();
        let institutions = institutions.clone();
        let selected_iid = selected_iid.clone();
        use_effect_with((), move |_| {
            let token = auth.api_token.clone();
            let key = auth.signing_key.clone();
            spawn_local(async move {
                if let (Some(token), Some(key)) = (token, key) {
                    let client = ApiClient { api_token: token, signing_key: key };
                    if let Ok(r) = client.get("/api/v1/master-data/institutions").await {
                        if let Ok(v) = r.json::<Vec<Institution>>().await {
                            if let Some(first) = v.first() {
                                selected_iid.set(first.id.clone());
                            }
                            institutions.set(v);
                        }
                    }
                }
            });
            || ()
        });
    }

    // Load dashboard when institution changes
    {
        let auth = auth.clone();
        let dashboard = dashboard.clone();
        let iid = (*selected_iid).clone();
        use_effect_with(iid.clone(), move |iid| {
            if iid.is_empty() { return || (); }
            let iid = iid.clone();
            let auth = auth.clone();
            let dashboard = dashboard.clone();
            dashboard.set(None);
            spawn_local(async move {
                if let (Some(token), Some(key)) = (auth.api_token.clone(), auth.signing_key.clone()) {
                    let client = ApiClient { api_token: token, signing_key: key };
                    let url = format!("/api/v1/analytics/dashboard?institution_id={}", iid);
                    match client.get(&url).await {
                        Ok(r) if r.ok() => match r.json::<DashboardView>().await {
                            Ok(v) => dashboard.set(Some(Ok(v))),
                            Err(e) => dashboard.set(Some(Err(e.to_string()))),
                        },
                        Ok(r) => dashboard.set(Some(Err(format!("HTTP {}", r.status())))),
                        Err(e) => dashboard.set(Some(Err(e.to_string()))),
                    }
                }
            });
            || ()
        });
    }

    let on_iid_change = {
        let selected_iid = selected_iid.clone();
        Callback::from(move |e: Event| {
            let el: web_sys::HtmlInputElement = e.target_unchecked_into();
            selected_iid.set(el.value());
        })
    };

    let iid_val = (*selected_iid).clone();

    html! {
        <>
            <div class="page-header">
                <h1>{"Analytics"}</h1>
                <p>{"Spend, throughput, and resident-care KPIs across institutions."}</p>
            </div>

            <Card>
                <div style="display:flex;align-items:center;gap:1rem;margin-bottom:1rem;">
                    <label><strong>{"Institution:"}</strong></label>
                    <select class="input" onchange={on_iid_change}>
                        { for (*institutions).iter().map(|i| {
                            let selected = i.id == iid_val;
                            html! {
                                <option value={i.id.clone()} selected={selected}>
                                    {format!("{} ({})", i.name, i.code)}
                                </option>
                            }
                        })}
                    </select>
                </div>
            </Card>

            { match (*dashboard).clone() {
                None if iid_val.is_empty() => html! {},
                None => html! { <Card><div style="text-align:center;padding:2rem;color:#888;">{"Loading dashboard…"}</div></Card> },
                Some(Err(e)) => html! { <Card><div style="color:red;padding:1rem;">{e}</div></Card> },
                Some(Ok(dash)) => html! {
                    <>
                        // Live counts
                        <Card>
                            <h2 style="margin-top:0;">{"Live Counts"}</h2>
                            <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:1rem;">
                                { live_card("Pending Requisitions", dash.live.pending_requisitions, "#f59e0b") }
                                { live_card("Open Orders", dash.live.open_orders, "#3b82f6") }
                                { live_card("Wellness (this week)", dash.live.wellness_sessions_this_week, "#10b981") }
                                { live_card("Moderation Queue", dash.live.moderation_queue_pending, "#ef4444") }
                                { live_card("Unacked Anomalies", dash.live.anomaly_events_unacked, "#8b5cf6") }
                            </div>
                        </Card>

                        // Recent daily stats
                        if !dash.recent_daily.is_empty() {
                            <Card>
                                <h2 style="margin-top:0;">{"Daily Stats (Last 7 Days)"}</h2>
                                <div style="overflow-x:auto;">
                                <table class="table" style="width:100%;">
                                    <thead><tr>
                                        <th>{"Date"}</th>
                                        <th>{"Requisitions"}</th>
                                        <th>{"Orders"}</th>
                                        <th>{"Supply Spend"}</th>
                                        <th>{"Approved Reqs"}</th>
                                    </tr></thead>
                                    <tbody>
                                    { for dash.recent_daily.iter().map(|d| {
                                        let get = |k: &str| d.stats.iter()
                                            .find(|s| s.stat_key == k)
                                            .map(|s| fmt_value(k, s.stat_value))
                                            .unwrap_or_else(|| "—".into());
                                        html! { <tr>
                                            <td>{&d.stat_date}</td>
                                            <td>{get("requisition_count")}</td>
                                            <td>{get("order_count")}</td>
                                            <td>{get("supply_spend_cents")}</td>
                                            <td>{get("approved_requisitions")}</td>
                                        </tr> }
                                    })}
                                    </tbody>
                                </table>
                                </div>
                            </Card>
                        }

                        // Recent weekly stats
                        if !dash.recent_weekly.is_empty() {
                            <Card>
                                <h2 style="margin-top:0;">{"Weekly Stats (Last 4 Weeks)"}</h2>
                                <div style="overflow-x:auto;">
                                <table class="table" style="width:100%;">
                                    <thead><tr>
                                        <th>{"Week Starting"}</th>
                                        <th>{"Requisitions"}</th>
                                        <th>{"Orders"}</th>
                                        <th>{"Wellness Sessions"}</th>
                                        <th>{"Supply Spend"}</th>
                                    </tr></thead>
                                    <tbody>
                                    { for dash.recent_weekly.iter().map(|w| {
                                        let get = |k: &str| w.stats.iter()
                                            .find(|s| s.stat_key == k)
                                            .map(|s| fmt_value(k, s.stat_value))
                                            .unwrap_or_else(|| "—".into());
                                        html! { <tr>
                                            <td>{&w.week_start}</td>
                                            <td>{get("requisition_count")}</td>
                                            <td>{get("order_count")}</td>
                                            <td>{get("wellness_sessions")}</td>
                                            <td>{get("supply_spend_cents")}</td>
                                        </tr> }
                                    })}
                                    </tbody>
                                </table>
                                </div>
                            </Card>
                        }

                        // Recent monthly stats
                        if !dash.recent_monthly.is_empty() {
                            <Card>
                                <h2 style="margin-top:0;">{"Monthly Stats (Last 3 Months)"}</h2>
                                <div style="overflow-x:auto;">
                                <table class="table" style="width:100%;">
                                    <thead><tr>
                                        <th>{"Month"}</th>
                                        { for ["requisition_count","order_count","supply_spend_cents","approved_requisitions"]
                                            .iter().map(|k| html! { <th>{fmt_stat(k)}</th> }) }
                                    </tr></thead>
                                    <tbody>
                                    { for dash.recent_monthly.iter().map(|m| {
                                        let get = |k: &str| m.stats.iter()
                                            .find(|s| s.stat_key == k)
                                            .map(|s| fmt_value(k, s.stat_value))
                                            .unwrap_or_else(|| "—".into());
                                        html! { <tr>
                                            <td>{&m.year_month}</td>
                                            <td>{get("requisition_count")}</td>
                                            <td>{get("order_count")}</td>
                                            <td>{get("supply_spend_cents")}</td>
                                            <td>{get("approved_requisitions")}</td>
                                        </tr> }
                                    })}
                                    </tbody>
                                </table>
                                </div>
                            </Card>
                        }

                        if dash.recent_daily.is_empty() && dash.recent_weekly.is_empty() && dash.recent_monthly.is_empty() {
                            <Card>
                                <p style="color:#888;text-align:center;padding:2rem;">
                                    {"No analytics data yet. Worker jobs will populate this after the first run (24h)."}
                                </p>
                            </Card>
                        }
                    </>
                },
            }}
        </>
    }
}

fn live_card(label: &str, value: i64, color: &str) -> Html {
    html! {
        <div style={format!("border:2px solid {};border-radius:8px;padding:1rem;text-align:center;", color)}>
            <div style={format!("font-size:2rem;font-weight:bold;color:{};", color)}>{value}</div>
            <div style="font-size:0.85rem;color:#555;margin-top:0.25rem;">{label}</div>
        </div>
    }
}
