/// Shows unacknowledged events first, allows acknowledgement.
use serde::Deserialize;
use wasm_bindgen_futures::spawn_local;
use yew::prelude::*;

use crate::auth::{use_auth, ApiClient};
use crate::components::card::Card;

#[derive(Clone, PartialEq, Deserialize, Debug)]
struct AnomalyEvent {
    id: String,
    rule_key: String,
    severity: String,
    subject_type: String,
    subject_value: String,
    detail: serde_json::Value,
    detected_at: String,
    acknowledged: bool,
    acknowledged_at: Option<String>,
}

#[derive(Clone, PartialEq, Deserialize, Debug)]
struct AnomalyRule {
    rule_key: String,
    label: String,
    description: String,
    threshold_count: i32,
    window_seconds: i32,
    severity: String,
    is_active: bool,
}

fn severity_badge(s: &str) -> Html {
    let (bg, fg) = match s {
        "critical" => ("#7f1d1d", "white"),
        "high" => ("#ef4444", "white"),
        "medium" => ("#f59e0b", "white"),
        _ => ("#6b7280", "white"),
    };
    html! {
        <span style={format!("background:{bg};color:{fg};padding:0.15rem 0.4rem;border-radius:3px;font-size:0.75rem;font-weight:bold;")}>
            {s.to_uppercase()}
        </span>
    }
}

#[function_component(SecurityEventsPage)]
pub fn security_events() -> Html {
    let auth = use_auth();
