1	use yew::prelude::*;
2	use yew_router::prelude::*;
3	
4	use crate::auth::use_auth;
5	use crate::router::Route;
6	
7	#[derive(Clone, PartialEq)]
8	pub struct NavGroup {
9	    pub label: &'static str,
10	    pub items: Vec<Route>,
11	}
12	
13	pub fn role_aware_groups() -> Vec<NavGroup> {
14	    // Phase 1: groups are role-aware in shape only — actual role gating is
15	    // wired in the auth phase. The structure already mirrors how the final
16	    // menu will collapse for non-admin roles.
17	    vec![
18	        NavGroup {
19	            label: "Operations",
20	            items: vec![Route::Dashboard, Route::Requisitions, Route::Approvals],
21	        },
22	        NavGroup {
23	            label: "Supply",
24	            items: vec![Route::Inventory, Route::Orders],
25	        },
26	        NavGroup {
27	            label: "Insights",
28	            items: vec![Route::Analytics],
29	        },
30	        NavGroup {
31	            label: "Residents",
32	            items: vec![Route::FamilyPortal],
33	        },
34	        NavGroup {
35	            label: "Admin",
36	            items: vec![Route::MasterData, Route::Settings],
37	        },
38	    ]
39	}
40	
41	#[derive(Properties, PartialEq)]
42	pub struct NavProps {
43	    pub current: Route,
44	}
45	
46	fn route_visible_for_roles(route: &Route, roles: &[String]) -> bool {
47	    let admin = roles.iter().any(|r| r == "admin");
48	    if admin { return true; }
49	    match route {
50	        Route::Dashboard => true,
51	        Route::RequisitionNew | Route::RequisitionDetail { .. } => true,
52	        Route::Requisitions | Route::Approvals => roles.iter().any(|r|
53	            matches!(r.as_str(), "medical" | "dept_approver" | "finance_approver")),
54	        Route::Inventory | Route::Orders => roles.iter().any(|r|
55	            matches!(r.as_str(), "finance_approver" | "medical")),
56	        Route::Analytics => roles.iter().any(|r| r == "finance_approver"),
57	        Route::FamilyPortal => roles.iter().any(|r| matches!(r.as_str(), "family" | "senior")),
58	        Route::MasterData | Route::Settings => false,
59	        _ => true,
60	    }
61	}
62	
63	#[function_component(SideNav)]
64	pub fn side_nav(props: &NavProps) -> Html {
65	    let auth = use_auth();
66	    let roles = auth.principal.as_ref().map(|p| p.roles.clone()).unwrap_or_default();
67	    let groups: Vec<NavGroup> = role_aware_groups()
68	        .into_iter()
69	        .map(|mut g| {
70	            g.items.retain(|r| route_visible_for_roles(r, &roles));
71	            g
72	        })
73	        .filter(|g| !g.items.is_empty())
74	        .collect();
75	    html! {
76	        <aside class="sidebar">
77	            <div class="brand">
78	                {"SilverOak"}
79	                <small>{"Operations Suite"}</small>
80	            </div>
81	            { for groups.into_iter().map(|g| render_group(g, &props.current)) }
82	        </aside>
83	    }
84	}
