9	/// Validate against the password policy. Phase 2 only enforces minimum
10	/// length per the Task Prompt; richer rules can be added without changing
11	/// callers.
12	pub fn validate_policy(password: &str) -> Result<(), ApiAppError> {
13	    if password.chars().count() < MIN_PASSWORD_LEN {
14	        return Err(ApiAppError::BadRequest(format!(
15	            "password must be at least {MIN_PASSWORD_LEN} characters"
16	        )));
17	    }
18	    Ok(())
19	}
