21	pub fn hash_password(password: &str) -> Result<String, ApiAppError> {
22	    validate_policy(password)?;
23	    let salt = SaltString::generate(&mut OsRng);
24	    let argon2 = Argon2::default();
25	    argon2
26	        .hash_password(password.as_bytes(), &salt)
27	        .map(|h| h.to_string())
28	        .map_err(|e| ApiAppError::Internal(format!("hash error: {e}")))
29	}
30	
31	pub fn verify_password(password: &str, encoded_hash: &str) -> bool {
32	    let Ok(parsed) = PasswordHash::new(encoded_hash) else {
33	        return false;
34	    };
35	    Argon2::default()
36	        .verify_password(password.as_bytes(), &parsed)
37	        .is_ok()
38	}
