11	type HmacSha256 = Hmac<Sha256>;
12	
13	/// Canonical string the client must sign:
14	///   METHOD\nPATH\nTIMESTAMP\nNONCE\nBODY_SHA256_HEX
15	///
16	/// The HMAC signing key is issued once at login (alongside the API token)
17	/// and held server-side in `api_tokens.signing_key`. The bearer token is
18	/// stored only as a SHA-256 hash so a DB leak alone does not yield usable
19	/// credentials. See `README.md#signed-requests` for the full flow.
20	pub struct RequestSigner;
21	
22	impl RequestSigner {
23	    /// Canonical string used by `SignedAuth`. The HTTP body is intentionally
24	    /// excluded so the middleware can authenticate without consuming the
25	    /// payload — body integrity rides on the TLS channel terminated at the
26	    /// reverse proxy.
27	    pub fn canonical_string_no_body(method: &str, path: &str, timestamp: &str, nonce: &str) -> String {
28	        format!("{}\n{}\n{}\n{}", method.to_uppercase(), path, timestamp, nonce)
29	    }
30	
31	    pub fn sign(signing_key: &str, canonical: &str) -> String {
32	        let mut mac = HmacSha256::new_from_slice(signing_key.as_bytes()).expect("hmac key");
33	        mac.update(canonical.as_bytes());
34	        hex::encode(mac.finalize().into_bytes())
35	    }
36	
37	    pub fn verify(signing_key: &str, canonical: &str, provided_hex: &str) -> bool {
38	        let expected = Self::sign(signing_key, canonical);
39	        // constant-time-ish: compare via byte equality after length check
40	        if expected.len() != provided_hex.len() {
41	            return false;
42	        }
43	        let mut diff = 0u8;
44	        for (a, b) in expected.as_bytes().iter().zip(provided_hex.as_bytes().iter()) {
45	            diff |= a ^ b;
46	        }
47	        diff == 0
48	    }
49	}
50	
51	/// Parse RFC3339 *or* unix-seconds and return a UTC datetime.
52	pub fn parse_timestamp(value: &str) -> Result<DateTime<Utc>, ApiAppError> {
53	    if let Ok(secs) = value.parse::<i64>() {
54	        return DateTime::<Utc>::from_timestamp(secs, 0)
55	            .ok_or_else(|| ApiAppError::BadRequest("invalid timestamp".into()));
56	    }
57	    DateTime::parse_from_rfc3339(value)
58	        .map(|d| d.with_timezone(&Utc))
59	        .map_err(|_| ApiAppError::BadRequest("invalid timestamp".into()))
60	}
61	
62	pub fn within_replay_window(ts: DateTime<Utc>) -> bool {
63	    let now = Utc::now();
64	    let skew = Duration::from_std(REPLAY_WINDOW).unwrap();
65	    ts >= now - skew && ts <= now + skew
66	}
67	
68	/// Persist a request signature so a replay within the window is rejected.
69	/// Returns `Err(BadRequest("replay"))` if already seen.
70	pub async fn record_signature(pool: &PgPool, user_id: Uuid, signature: &str) -> Result<(), ApiAppError> {
71	    let expires_at = Utc::now() + Duration::from_std(REPLAY_WINDOW).unwrap() * 2;
72	    let res = sqlx::query(
73	        "INSERT INTO used_signatures (signature, user_id, expires_at) VALUES ($1, $2, $3)
74	         ON CONFLICT (signature) DO NOTHING",
75	    )
76	    .bind(signature)
77	    .bind(user_id)
78	    .bind(expires_at)
79	    .execute(pool)
80	    .await
81	    .map_err(|e| ApiAppError::Internal(e.to_string()))?;
82	    if res.rows_affected() == 0 {
83	        return Err(ApiAppError::BadRequest("replayed request signature".into()));
84	    }
85	    Ok(())
86	}
87	
88	/// Best-effort cleanup of expired entries; called by the worker but exposed
89	/// here so tests and admin endpoints can trigger it too.
90	pub async fn purge_expired_signatures(pool: &PgPool) -> Result<u64> {
91	    let res = sqlx::query("DELETE FROM used_signatures WHERE expires_at < NOW()")
92	        .execute(pool)
93	        .await?;
94	    Ok(res.rows_affected())
95	}
