103	        let canon = RequestSigner::canonical_string_no_body(
104	            "POST",
105	            "/api/v1/things",
106	            "1700000000",
107	            "nonce-123",
108	        );
109	        let sig = RequestSigner::sign("secret-key", &canon);
110	        assert!(RequestSigner::verify("secret-key", &canon, &sig));
111	        assert!(!RequestSigner::verify("other-key", &canon, &sig));
112	        assert!(!RequestSigner::verify("secret-key", &canon, "deadbeef"));
