119	        assert!(within_replay_window(now - Duration::seconds(59)));
120	        assert!(within_replay_window(now + Duration::seconds(59)));
121	        assert!(!within_replay_window(now - Duration::seconds(120)));
122	        assert!(!within_replay_window(now + Duration::seconds(120)));
