52	/// Centralized transition validator. Every status change MUST go through
53	/// here — services call `Transition::check(from, to)?` before any DB write.
54	/// This is the only place where the requisition lifecycle is encoded.
55	pub struct Transition;
56	
57	impl Transition {
58	    pub fn check(from: ReqStatus, to: ReqStatus) -> Result<(), ApiAppError> {
59	        let allowed = matches!(
60	            (from, to),
61	            (ReqStatus::Draft,            ReqStatus::PendingApproval) |
62	            (ReqStatus::Draft,            ReqStatus::Withdrawn)       |
63	            (ReqStatus::SentBack,         ReqStatus::PendingApproval) |
64	            (ReqStatus::SentBack,         ReqStatus::Withdrawn)       |
65	            (ReqStatus::PendingApproval,  ReqStatus::SentBack)        |
66	            (ReqStatus::PendingApproval,  ReqStatus::Rejected)        |
67	            (ReqStatus::PendingApproval,  ReqStatus::ApprovedFinal)   |
68	            (ReqStatus::PendingApproval,  ReqStatus::Withdrawn)       |
69	            (ReqStatus::ApprovedFinal,    ReqStatus::Issued)
70	        );
71	        if allowed {
72	            Ok(())
73	        } else {
74	            Err(ApiAppError::BadRequest(format!(
75	                "invalid transition: {} → {}",
76	                from.as_str(),
77	                to.as_str()
