104	/// Effective unit price for a (product, user_roles, quantity) triple.
105	/// Returns `(unit_price_cents, member_applied, threshold_applied, discount_bps)`.
106	pub async fn effective_price(
107	    pool: &PgPool,
108	    product: &ProductRow,
109	    user_roles: &[String],
110	    quantity: i32,
111	) -> Result<(i64, bool, bool, i32), ApiAppError> {
112	    // 1. member price
113	    let member: Option<(i64,)> = sqlx::query_as(
114	        "SELECT price_cents FROM product_pricing
115	         WHERE product_id = $1 AND role_key = ANY($2)
116	         ORDER BY price_cents LIMIT 1",
117	    )
118	    .bind(product.id)
119	    .bind(user_roles)
120	    .fetch_optional(pool)
121	    .await?;
122	
123	    // 2. best threshold discount for this quantity
124	    let threshold: Option<(i32,)> = sqlx::query_as(
125	        "SELECT discount_bps FROM product_threshold_discounts
126	         WHERE product_id = $1 AND min_quantity <= $2
127	         ORDER BY discount_bps DESC LIMIT 1",
128	    )
129	    .bind(product.id)
130	    .bind(quantity)
131	    .fetch_optional(pool)
132	    .await?;
133	
134	    let base = product.base_price_cents;
135	
136	    match (member, threshold) {
137	        (Some((mp,)), Some((bps,))) => {
138	            // Both available — pick whichever gives the lower price.
139	            let threshold_price = base - (base * bps as i64 / 10000);
140	            if mp <= threshold_price {
141	                Ok((mp, true, false, 0))
142	            } else {
143	                Ok((threshold_price, false, true, bps))
144	            }
145	        }
146	        (Some((mp,)), None) => Ok((mp, true, false, 0)),
147	        (None, Some((bps,))) => {
148	            let p = base - (base * bps as i64 / 10000);
149	            Ok((p, false, true, bps))
150	        }
151	        (None, None) => Ok((base, false, false, 0)),
152	    }
153	}
