166	pub async fn price_cart(pool: &PgPool, input: &CartInput) -> Result<PricingSummary, ApiAppError> {
167	    let mut priced_lines: Vec<PricedLine> = Vec::new();
168	    let mut any_member = false;
169	    let mut any_threshold = false;
170	
171	    for (product_id, qty) in &input.lines {
172	        let product = load_product(pool, *product_id).await?;
173	        let (unit_price, member_applied, threshold_applied, discount_bps) =
174	            effective_price(pool, &product, &input.user_roles, *qty).await?;
175	
176	        if member_applied { any_member = true; }
177	        if threshold_applied { any_threshold = true; }
178	
179	        priced_lines.push(PricedLine {
180	            product_id: *product_id,
181	            sku: product.sku,
182	            name: product.name,
183	            quantity: *qty,
184	            base_price_cents: product.base_price_cents,
185	            unit_price_cents: unit_price,
186	            line_total_cents: unit_price * *qty as i64,
187	            member_price_applied: member_applied,
188	            threshold_discount_applied: threshold_applied,
189	            discount_bps,
190	            stock: product.stock,
191	        });
192	    }
193	
194	    let subtotal: i64 = priced_lines.iter().map(|l| l.line_total_cents).sum();
195	
196	    // Coupon
197	    let (coupon_discount_cents, coupon_applied, coupon_code, coupon_blocked_reason) =
198	        if let Some(coupon_id) = input.coupon_id {
199	            apply_coupon(pool, coupon_id, subtotal, any_member, any_threshold).await?
200	        } else {
201	            (0, false, None, None)
202	        };
203	
204	    // Bundle warnings
205	    let bundle_warnings = check_bundles(pool, &priced_lines).await?;
206	
207	    // Purchase limit warnings
208	    let purchase_limit_warnings =
209	        check_daily_limits(pool, input.user_id, &priced_lines).await?;
210	
211	    let total = subtotal + input.delivery_fee_cents - coupon_discount_cents;
212	
213	    Ok(PricingSummary {
214	        lines: priced_lines,
215	        subtotal_cents: subtotal,
216	        delivery_fee_cents: input.delivery_fee_cents,
217	        coupon_discount_cents,
218	        total_cents: total.max(0),
219	        coupon_applied,
220	        coupon_code,
221	        coupon_blocked_reason,
222	        bundle_warnings,
223	        purchase_limit_warnings,
224	    })
225	}
