227	async fn apply_coupon(
228	    pool: &PgPool,
229	    coupon_id: Uuid,
230	    subtotal: i64,
231	    any_member: bool,
232	    any_threshold: bool,
233	) -> Result<(i64, bool, Option<String>, Option<String>), ApiAppError> {
234	    let row: Option<(String, i32, bool, bool, bool, Option<i64>, Option<i32>)> = sqlx::query_as(
235	        "SELECT code, discount_bps, stackable_with_member_price, stackable_with_threshold,
236	                is_active, EXTRACT(EPOCH FROM (valid_until - NOW()))::BIGINT,
237	                CASE WHEN max_uses IS NULL THEN NULL ELSE max_uses - times_used END
238	         FROM coupons WHERE id = $1",
239	    )
240	    .bind(coupon_id)
241	    .fetch_optional(pool)
242	    .await?;
243	    let (code, bps, stack_member, stack_threshold, is_active, secs_left, uses_left) =
244	        match row {
245	            Some(r) => r,
246	            None => return Ok((0, false, None, Some("coupon not found".into()))),
247	        };
248	
249	    if !is_active {
250	        return Ok((0, false, Some(code), Some("coupon inactive".into())));
251	    }
252	    if secs_left.map(|s| s < 0).unwrap_or(false) {
253	        return Ok((0, false, Some(code), Some("coupon expired".into())));
254	    }
255	    if uses_left.map(|u| u <= 0).unwrap_or(false) {
256	        return Ok((0, false, Some(code), Some("coupon exhausted".into())));
257	    }
258	    if any_member && !stack_member {
259	        return Ok((0, false, Some(code),
260	            Some("coupon cannot stack with member pricing".into())));
261	    }
262	    if any_threshold && !stack_threshold {
263	        return Ok((0, false, Some(code),
264	            Some("coupon cannot stack with threshold discount".into())));
265	    }
266	
267	    let discount = subtotal * bps as i64 / 10000;
268	    Ok((discount, true, Some(code), None))
269	}
