271	async fn check_bundles(
272	    pool: &PgPool,
273	    lines: &[PricedLine],
274	) -> Result<Vec<BundleWarning>, ApiAppError> {
275	    if lines.is_empty() { return Ok(vec![]); }
276	    let product_ids: Vec<Uuid> = lines.iter().map(|l| l.product_id).collect();
277	
278	    let bundles: Vec<(Uuid, String, String, i32, String)> = sqlx::query_as(
279	        "SELECT b.id, b.key, b.label, b.threshold_qty, b.warning_message
280	         FROM product_bundles b
281	         JOIN product_bundle_members m ON m.bundle_id = b.id
282	         WHERE m.product_id = ANY($1)
283	         GROUP BY b.id, b.key, b.label, b.threshold_qty, b.warning_message",
284	    )
285	    .bind(&product_ids)
286	    .fetch_all(pool)
287	    .await?;
288	
289	    let mut warnings = Vec::new();
290	    for (bundle_id, key, label, threshold_qty, warning_message) in bundles {
291	        // Sum quantities of products that are in this bundle AND in the cart.
292	        let members: Vec<(Uuid,)> = sqlx::query_as(
293	            "SELECT product_id FROM product_bundle_members WHERE bundle_id = $1",
294	        )
295	        .bind(bundle_id)
296	        .fetch_all(pool)
297	        .await?;
298	        let member_ids: Vec<Uuid> = members.into_iter().map(|m| m.0).collect();
299	        let total_qty: i32 = lines.iter()
300	            .filter(|l| member_ids.contains(&l.product_id))
301	            .map(|l| l.quantity)
302	            .sum();
303	
304	        if total_qty >= threshold_qty {
305	            warnings.push(BundleWarning {
306	                bundle_key: key,
307	                label,
308	                warning_message,
309	                total_qty,
310	                threshold_qty,
311	            });
312	        }
313	    }
314	    Ok(warnings)
315	}
