317	async fn check_daily_limits(
318	    pool: &PgPool,
319	    user_id: Uuid,
320	    lines: &[PricedLine],
321	) -> Result<Vec<String>, ApiAppError> {
322	    let mut warnings = Vec::new();
323	    for line in lines {
324	        let existing: Option<(i32,)> = sqlx::query_as(
325	            "SELECT quantity FROM daily_purchase_tracking
326	             WHERE user_id=$1 AND product_id=$2 AND purchase_date=CURRENT_DATE",
327	        )
328	        .bind(user_id)
329	        .bind(line.product_id)
330	        .fetch_optional(pool)
331	        .await?;
332	        let already = existing.map(|r| r.0).unwrap_or(0);
333	        if already + line.quantity > DAILY_LIMIT_PER_SKU {
334	            warnings.push(format!(
335	                "{} ({}): daily limit {} — already purchased {}, requesting {}",
336	                line.name, line.sku, DAILY_LIMIT_PER_SKU, already, line.quantity
337	            ));
338	        }
339	    }
340	    Ok(warnings)
341	}
