1	//! Field-level AES-256-GCM encryption for sensitive TEXT columns.
2	//!
3	//! Encrypted values are stored as `base64(nonce):base64(ciphertext)`.
4	//! The encryption key is loaded once from the `SILVEROAK_FIELD_KEY`
5	//! environment variable (base64-encoded 32 bytes) and cached for the
6	//! lifetime of the process.
7	//!
8	//! # Security note
9	//! NEVER log plaintext values. All log statements in this module are
10	//! restricted to error kinds and byte lengths only.
11	
12	use std::sync::OnceLock;
13	
14	use aes_gcm::{
15	    aead::{Aead, KeyInit, OsRng, rand_core::RngCore},
16	    Aes256Gcm, Key, Nonce,
17	};
18	use base64::{engine::general_purpose::STANDARD as B64, Engine};
19	
20	// ---------------------------------------------------------------------------
21	// Error type
22	// ---------------------------------------------------------------------------
23	
24	/// Errors produced by the crypto module.
25	#[derive(Debug)]
26	pub enum CryptoError {
27	    /// The stored value is not in the expected `nonce:ciphertext` format.
28	    InvalidFormat,
29	    /// Base64 decoding failed.
30	    Base64Decode(base64::DecodeError),
31	    /// AES-GCM encryption or decryption failed.
32	    Aead(String),
33	    /// The encryption key could not be loaded or is the wrong length.
34	    KeyError(String),
35	}
36	
37	impl std::fmt::Display for CryptoError {
38	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
39	        match self {
40	            CryptoError::InvalidFormat => {
41	                write!(f, "encrypted value is not in 'nonce:ciphertext' format")
42	            }
43	            CryptoError::Base64Decode(e) => write!(f, "base64 decode error: {e}"),
44	            CryptoError::Aead(msg) => write!(f, "AES-GCM error: {msg}"),
45	            CryptoError::KeyError(msg) => write!(f, "key error: {msg}"),
46	        }
47	    }
48	}
49	
50	impl std::error::Error for CryptoError {
51	    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
52	        match self {
53	            CryptoError::Base64Decode(e) => Some(e),
54	            _ => None,
55	        }
56	    }
57	}
58	
59	impl From<base64::DecodeError> for CryptoError {
60	    fn from(e: base64::DecodeError) -> Self {
61	        CryptoError::Base64Decode(e)
62	    }
63	}
64	
65	// ---------------------------------------------------------------------------
66	// Key management
67	// ---------------------------------------------------------------------------
68	
69	/// 32-byte dev-only fallback key. Used only when `SILVEROAK_FIELD_KEY` is
70	/// absent. NOT safe for production.
71	const DEV_FALLBACK_KEY: &[u8; 32] = b"silveroak-dev-key-NOT-FOR-PROD!!";
72	
73	static CIPHER: OnceLock<Aes256Gcm> = OnceLock::new();
74	
75	/// Returns (or initialises) the process-wide AES-256-GCM cipher.
76	///
77	/// On first call the key is read from `SILVEROAK_FIELD_KEY`. If the variable
78	/// is absent a loud warning is emitted and the dev fallback key is used.
79	fn cipher() -> Result<&'static Aes256Gcm, CryptoError> {
80	    CIPHER.get_or_try_init(|| {
81	        let key_bytes: Vec<u8> = match std::env::var("SILVEROAK_FIELD_KEY") {
82	            Ok(encoded) => {
83	                let decoded = B64.decode(encoded.trim()).map_err(|e| {
84	                    CryptoError::KeyError(format!("SILVEROAK_FIELD_KEY base64 decode failed: {e}"))
85	                })?;
86	                if decoded.len() != 32 {
87	                    return Err(CryptoError::KeyError(format!(
88	                        "SILVEROAK_FIELD_KEY must decode to exactly 32 bytes, got {}",
89	                        decoded.len()
90	                    )));
91	                }
92	                decoded
93	            }
94	            Err(_) => {
95	                // NEVER log the key value itself — only the warning.
96	                tracing::warn!(
97	                    "SILVEROAK_FIELD_KEY is not set. \
98	                     Using the dev-only fallback encryption key. \
99	                     THIS IS INSECURE AND MUST NOT BE USED IN PRODUCTION."
100	                );
101	                DEV_FALLBACK_KEY.to_vec()
102	            }
103	        };
104	
105	        let key = Key::<Aes256Gcm>::from_slice(&key_bytes);
106	        Ok(Aes256Gcm::new(key))
107	    })
108	}
109	
110	// ---------------------------------------------------------------------------
111	// Public API
112	// ---------------------------------------------------------------------------
113	
114	/// Encrypts `plaintext` with AES-256-GCM using a freshly generated 12-byte
115	/// (96-bit) nonce.
116	///
117	/// Returns `base64(nonce):base64(ciphertext)`.
118	///
119	/// # Security
120	/// NEVER log the plaintext argument; log only lengths or error kinds.
121	pub fn encrypt(plaintext: &str) -> Result<String, CryptoError> {
122	    let cipher = cipher()?;
123	
124	    // Generate a random 12-byte nonce (96 bits — standard for GCM).
125	    let mut nonce_bytes = [0u8; 12];
126	    OsRng.fill_bytes(&mut nonce_bytes);
127	    let nonce = Nonce::from_slice(&nonce_bytes);
128	
129	    let ciphertext = cipher
130	        .encrypt(nonce, plaintext.as_bytes())
131	        .map_err(|e| CryptoError::Aead(e.to_string()))?;
132	
133	    let encoded = format!("{}:{}", B64.encode(nonce_bytes), B64.encode(&ciphertext));
134	    Ok(encoded)
135	}
136	
137	/// Decrypts a value produced by [`encrypt`].
138	///
139	/// Expects the format `base64(nonce):base64(ciphertext)`.
140	///
141	/// # Security
142	/// NEVER log the returned plaintext; log only lengths or error kinds.
143	pub fn decrypt(ciphertext: &str) -> Result<String, CryptoError> {
144	    let cipher = cipher()?;
145	
146	    let (nonce_b64, ct_b64) = ciphertext
147	        .split_once(':')
148	        .ok_or(CryptoError::InvalidFormat)?;
149	
150	    let nonce_bytes = B64.decode(nonce_b64)?;
151	    if nonce_bytes.len() != 12 {
152	        return Err(CryptoError::InvalidFormat);
153	    }
154	    let nonce = Nonce::from_slice(&nonce_bytes);
155	
156	    let ct_bytes = B64.decode(ct_b64)?;
157	
158	    let plaintext_bytes = cipher
159	        .decrypt(nonce, ct_bytes.as_slice())
160	        .map_err(|e| CryptoError::Aead(e.to_string()))?;
161	
162	    String::from_utf8(plaintext_bytes)
163	        .map_err(|e| CryptoError::Aead(format!("UTF-8 decode failed: {e}")))
164	}
165	
166	/// Returns `true` when `value` looks like an encrypted blob (contains `:`).
167	///
168	/// This is a heuristic only — a plain string containing `:` would also match.
169	/// Use it as a quick guard before calling [`decrypt`].
170	pub fn is_encrypted(value: &str) -> bool {
171	    value.contains(':')
172	}
173	
174	// ---------------------------------------------------------------------------
175	// Tests
176	// ---------------------------------------------------------------------------
177	
178	#[cfg(test)]
179	mod tests {
180	    use super::*;
181	
182	    #[test]
183	    fn round_trip() {
184	        // NEVER assert or print the plaintext in log output during tests.
185	        let plaintext = "sensitive-data-12345";
186	        let encrypted = encrypt(plaintext).expect("encrypt should succeed");
187	        assert!(is_encrypted(&encrypted), "encrypted value must contain ':'");
188	        let decrypted = decrypt(&encrypted).expect("decrypt should succeed");
189	        assert_eq!(decrypted, plaintext);
190	    }
191	
192	    #[test]
193	    fn different_nonces_produce_different_ciphertexts() {
194	        let plaintext = "same input";
195	        let ct1 = encrypt(plaintext).unwrap();
196	        let ct2 = encrypt(plaintext).unwrap();
197	        // Nonces are random so ciphertexts must differ.
198	        assert_ne!(ct1, ct2);
199	    }
200	
201	    #[test]
202	    fn invalid_format_returns_error() {
203	        let result = decrypt("notvalidbase64withoutcolon");
204	        assert!(matches!(result, Err(CryptoError::InvalidFormat)));
205	    }
206	
207	    #[test]
208	    fn is_encrypted_heuristic() {
209	        assert!(is_encrypted("abc:def"));
210	        assert!(!is_encrypted("nodivider"));
211	    }
212	}
