        ).bind(pid).execute(pool).await;
        // Don't fail if ON CONFLICT not applicable - just ignore errors
    } else {
        let _ = sqlx::query(
            "INSERT INTO moderation_queue
                 (content_type, content_snippet, matched_keywords, severity, status, content_ref_id)
             VALUES ('wellness_note', 'Resident reported pain during morning exercises', ARRAY['pain'], 'low', 'pending', gen_random_uuid())
             ON CONFLICT DO NOTHING"
        ).execute(pool).await;
    }

    // --- Sample anomaly event ---
    let _ = sqlx::query(
        "INSERT INTO anomaly_events
