    if let Some((student_id,)) = student {
        let _ = sqlx::query(
            "INSERT INTO wellness_activities
                 (student_id, activity_type, duration_minutes, activity_date, notes_encrypted)
             VALUES ($1, 'walking', 30, NOW()::date - 1, 'Completed morning walk without assistance')
             ON CONFLICT DO NOTHING"
        ).bind(student_id).execute(pool).await;
    }

    tracing::info!("sample data seed complete");
    Ok(())
}
