1	use serde::{Deserialize, Serialize};
2	use sqlx::PgPool;
3	use uuid::Uuid;
4	
5	use crate::error::ApiAppError;
6	
7	/// Snapshot of a requisition the engine evaluates against.
8	#[derive(Debug, Clone)]
9	pub struct ReqSnapshot {
10	    pub total_amount_cents: i64,
11	    pub contains_controlled: bool,
12	}
13	
14	#[derive(Debug, Clone, Serialize, Deserialize)]
15	pub struct Condition {
16	    pub kind: String,
17	    pub threshold_cents: Option<i64>,
18	}
19	
20	impl Condition {
21	    pub fn matches(&self, snap: &ReqSnapshot) -> bool {
22	        match self.kind.as_str() {
23	            "always" => true,
24	            "amount_gt_cents" => self
25	                .threshold_cents
26	                .map(|t| snap.total_amount_cents > t)
27	                .unwrap_or(false),
28	            "contains_controlled" => snap.contains_controlled,
29	            _ => false,
30	        }
31	    }
32	}
33	
34	#[derive(Debug, Clone, Serialize)]
35	pub struct ResolvedNode {
36	    pub node_id: Uuid,
37	    pub sequence: i32,
38	    pub label: String,
39	    pub required_role: String,
40	}
41	
42	/// Pure rule evaluator. Walks the workflow's nodes in sequence; a node
43	/// is included when ANY of its conditions match (OR semantics). The
44	/// resulting list IS the approval route for this requisition.
45	pub async fn resolve_route(
46	    pool: &PgPool,
47	    workflow_id: Uuid,
48	    snap: &ReqSnapshot,
49	) -> Result<Vec<ResolvedNode>, ApiAppError> {
50	    let nodes: Vec<(Uuid, i32, String, String)> = sqlx::query_as(
51	        "SELECT id, sequence, label, required_role
52	         FROM approval_nodes WHERE workflow_id = $1 ORDER BY sequence",
53	    )
54	    .bind(workflow_id)
55	    .fetch_all(pool)
56	    .await?;
57	
58	    let mut resolved = Vec::new();
59	    for (id, seq, label, role) in nodes {
60	        let conds: Vec<(String, Option<i64>)> = sqlx::query_as(
61	            "SELECT condition_kind, threshold_cents FROM approval_rule_conditions WHERE node_id = $1",
62	        )
63	        .bind(id)
64	        .fetch_all(pool)
65	        .await?;
66	
67	        let included = conds.iter().any(|(k, t)| {
68	            Condition { kind: k.clone(), threshold_cents: *t }.matches(snap)
69	        });
70	        if included {
71	            resolved.push(ResolvedNode {
72	                node_id: id,
73	                sequence: seq,
74	                label,
75	                required_role: role,
76	            });
77	        }
78	    }
79	
80	    if resolved.is_empty() {
81	        return Err(ApiAppError::Internal(
82	            "approval workflow resolved to zero nodes".into(),
83	        ));
84	    }
85	    Ok(resolved)
86	}
87	
88	#[cfg(test)]
89	mod tests {
90	    use super::*;
91	    #[test]
92	    fn condition_matchers() {
93	        let snap = ReqSnapshot { total_amount_cents: 300_000, contains_controlled: false };
94	        assert!(Condition { kind: "always".into(), threshold_cents: None }.matches(&snap));
95	        assert!(Condition { kind: "amount_gt_cents".into(), threshold_cents: Some(250_000) }.matches(&snap));
96	        assert!(!Condition { kind: "amount_gt_cents".into(), threshold_cents: Some(500_000) }.matches(&snap));
97	        assert!(!Condition { kind: "contains_controlled".into(), threshold_cents: None }.matches(&snap));
