132	    pool: &PgPool,
133	    p: &Principal,
134	    input: CreateRequisitionInput,
135	) -> Result<RequisitionDetail, ApiAppError> {
136	    p.require("requisitions:write")?;
137	    assert_dept_scope(p, input.department_id)?;
138	    if input.justification.trim().is_empty() {
139	        return Err(ApiAppError::BadRequest("justification required".into()));
140	    }
141	    if input.lines.is_empty() {
142	        return Err(ApiAppError::BadRequest("at least one line required".into()));
143	    }
144	    for l in &input.lines {
145	        if l.quantity <= 0 {
146	            return Err(ApiAppError::BadRequest("quantities must be > 0".into()));
147	        }
148	    }
149	
150	    let mut tx = pool.begin().await?;
151	
152	    // Derive the site from the department.
153	    let site_row: Option<(Uuid,)> = sqlx::query_as("SELECT site_id FROM departments WHERE id=$1")
154	        .bind(input.department_id).fetch_optional(&mut *tx).await?;
155	    let site_id = site_row.ok_or_else(|| ApiAppError::BadRequest("unknown department".into()))?.0;
156	
157	    // Look up items + categories + on_hand at the requisition's site.
158	    let mut total: i64 = 0;
159	    let mut controlled = false;
160	    let mut prepared: Vec<(Uuid, i32, i64, i64)> = Vec::new();
161	    for l in &input.lines {
162	        let row: Option<(i64, bool)> = sqlx::query_as(
163	            "SELECT i.unit_price_cents, c.controlled
164	             FROM inventory_items i JOIN inventory_categories c ON c.id = i.category_id
165	             WHERE i.id = $1 AND i.is_active",
166	        )
167	        .bind(l.item_id)
168	        .fetch_optional(&mut *tx)
169	        .await?;
170	        let (unit_price, ctrl) = row.ok_or_else(|| ApiAppError::BadRequest("item not found".into()))?;
171	        let line_total = unit_price * l.quantity as i64;
172	        total += line_total;
173	        if ctrl { controlled = true; }
174	        prepared.push((l.item_id, l.quantity, unit_price, line_total));
175	    }
176	
177	    let ref_code = next_ref_code(&mut tx).await?;
178	    let req_id: (Uuid,) = sqlx::query_as(
179	        "INSERT INTO requisitions
180	            (ref_code, requester_id, site_id, department_id, status,
181	             needed_by, justification, total_amount_cents, contains_controlled)
182	         VALUES ($1, $2, $3, $4, 'draft', $5, $6, $7, $8) RETURNING id",
183	    )
184	    .bind(&ref_code)
185	    .bind(p.user_id)
186	    .bind(site_id)
