188	    .bind(input.needed_by)
189	    .bind(input.justification.trim())
190	    .bind(total)
191	    .bind(controlled)
192	    .fetch_one(&mut *tx)
193	    .await?;
194	
195	    for (item_id, qty, unit_price, line_total) in prepared {
196	        sqlx::query(
197	            "INSERT INTO requisition_lines (requisition_id, item_id, quantity, unit_price_cents, line_total_cents)
198	             VALUES ($1,$2,$3,$4,$5)",
