251	pub async fn withdraw(pool: &PgPool, p: &Principal, req_id: Uuid) -> Result<RequisitionDetail, ApiAppError> {
252	    let row: Option<(Uuid, String)> = sqlx::query_as("SELECT requester_id, status FROM requisitions WHERE id=$1")
253	        .bind(req_id).fetch_optional(pool).await?;
254	    let (requester, status) = row.ok_or(ApiAppError::NotFound)?;
255	    assert_owner(p, requester)?;
256	    let cur = ReqStatus::parse(&status).unwrap();
257	    if !cur.is_withdrawable() {
258	        return Err(ApiAppError::BadRequest(format!("cannot withdraw from {}", cur.as_str())));
259	    }
