278	async fn current_pending_step(
279	    pool: &PgPool,
280	    req_id: Uuid,
281	) -> Result<(Uuid, Uuid, i32, String), ApiAppError> {
282	    // (instance_id, step_id, sequence, required_role) for the next undecided step
283	    let row: Option<(Uuid, Uuid, i32, String)> = sqlx::query_as(
284	        "SELECT s.instance_id, s.id, s.sequence, s.required_role
285	         FROM requisition_approval_steps s
286	         JOIN requisition_approval_instances i ON i.id = s.instance_id
287	         WHERE i.requisition_id = $1 AND i.status='in_progress' AND s.decision IS NULL
288	         ORDER BY s.sequence LIMIT 1",
289	    )
290	    .bind(req_id).fetch_optional(pool).await?;
291	    row.ok_or_else(|| ApiAppError::BadRequest("no pending approval step".into()))
292	}
