294	fn assert_can_act_at_step(p: &Principal, required_role: &str) -> Result<(), ApiAppError> {
295	    if p.has_role(required_role) || p.permissions.contains("*") {
296	        Ok(())
297	    } else {
298	        Err(ApiAppError::Forbidden(format!("requires role {required_role}")))
299	    }
300	}
301	
302	pub async fn approve(
303	    pool: &PgPool,
304	    p: &Principal,
305	    req_id: Uuid,
306	    input: DecisionInput,
307	) -> Result<RequisitionDetail, ApiAppError> {
308	    p.require("requisitions:approve")?;
309	    let (instance_id, step_id, sequence, role) = current_pending_step(pool, req_id).await?;
310	    assert_can_act_at_step(p, &role)?;
311	
312	    // Determine if this is the LAST step.
313	    let total_steps: (i64,) =
314	        sqlx::query_as("SELECT COUNT(*) FROM requisition_approval_steps WHERE instance_id=$1")
315	            .bind(instance_id).fetch_one(pool).await?;
316	    let is_final = sequence as i64 == total_steps.0;
317	
318	    if !is_final {
319	        // Just record the step decision; status stays pending_approval.
320	        let mut tx = pool.begin().await?;
321	        sqlx::query(
322	            "UPDATE requisition_approval_steps SET decision='approved', decided_by=$2, decided_at=NOW(), reason=$3 WHERE id=$1",
323	        )
324	        .bind(step_id).bind(p.user_id).bind(input.comment.as_deref())
325	        .execute(&mut *tx).await?;
326	        sqlx::query("UPDATE requisition_approval_instances SET current_step=$2 WHERE id=$1")
327	            .bind(instance_id).bind(sequence).execute(&mut *tx).await?;
328	        audit(&mut tx, req_id, Some(p.user_id), "approved_step",
329	              input.comment.as_deref()).await?;
330	        tx.commit().await?;
331	        return load_detail(pool, p, req_id).await;
332	    }
333	
334	    // FINAL APPROVAL — the high-risk path.
335	    finalize_in_transaction(pool, p, req_id, instance_id, step_id, input.comment.as_deref()).await?;
336	    load_detail(pool, p, req_id).await
337	}
