565	
566	    let route: Vec<(i32, String, String, Option<String>, Option<Uuid>, Option<String>)> = sqlx::query_as(
567	        "SELECT s.sequence, n.label, s.required_role, s.decision, s.decided_by, s.reason
568	         FROM requisition_approval_steps s
569	         JOIN approval_nodes n ON n.id = s.node_id
570	         JOIN requisition_approval_instances i ON i.id = s.instance_id
571	         WHERE i.requisition_id = $1 ORDER BY s.sequence",
572	    ).bind(req_id).fetch_all(pool).await?;
573	
574	    let audit_rows: Vec<(chrono::DateTime<chrono::Utc>, Option<Uuid>, String, Option<String>)> = sqlx::query_as(
