361	// ── verify: re-price and save snapshot -----------------------------------
362	pub async fn verify_cart(pool: &PgPool, p: &Principal) -> Result<PricingSummary, ApiAppError> {
363	    p.require("orders:write")?;
364	    let cart_id = active_cart_id(pool, p.user_id).await?;
365	
366	    let cart: (Option<Uuid>, Option<Uuid>) = sqlx::query_as(
367	        "SELECT coupon_id, delivery_method_id FROM carts WHERE id=$1",
368	    )
369	    .bind(cart_id)
370	    .fetch_one(pool)
371	    .await?;
372	
373	    if cart.1.is_none() {
374	        return Err(ApiAppError::BadRequest("select a delivery method before verifying".into()));
375	    }
376	
377	    let lines: Vec<(Uuid, i32)> = sqlx::query_as(
378	        "SELECT product_id, quantity FROM cart_lines WHERE cart_id=$1 ORDER BY product_id",
379	    )
380	    .bind(cart_id)
381	    .fetch_all(pool)
382	    .await?;
383	
384	    if lines.is_empty() {
385	        return Err(ApiAppError::BadRequest("cart is empty".into()));
386	    }
387	
388	    let delivery_fee: (i64,) = sqlx::query_as("SELECT fee_cents FROM delivery_methods WHERE id=$1")
389	        .bind(cart.1.unwrap()).fetch_one(pool).await?;
390	
391	    let summary = price_cart(pool, &CartInput {
392	        lines: lines.clone(),
393	        coupon_id: cart.0,
394	        delivery_fee_cents: delivery_fee.0,
395	        user_roles: p.roles.clone(),
396	        user_id: p.user_id,
397	    }).await?;
398	
399	    // Check stock availability
400	    for line in &summary.lines {
401	        if line.stock < line.quantity {
402	            return Err(ApiAppError::BadRequest(format!(
403	                "{}: only {} in stock, requested {}",
404	                line.name, line.stock, line.quantity
405	            )));
406	        }
407	    }
408	
409	    // Enforce purchase limits during verify (not just warn)
410	    if !summary.purchase_limit_warnings.is_empty() {
411	        return Err(ApiAppError::BadRequest(format!(
412	            "daily limit exceeded: {}",
413	            summary.purchase_limit_warnings.join("; ")
414	        )));
415	    }
416	
417	    // Save snapshot
418	    let snapshot_json = serde_json::to_value(&summary)
419	        .map_err(|e| ApiAppError::Internal(e.to_string()))?;
420	    let expires_at = Utc::now() + Duration::seconds(SNAPSHOT_TTL_SECS);
421	
422	    // Invalidate old snapshots for this cart
423	    sqlx::query("DELETE FROM order_verification_snapshots WHERE cart_id=$1")
424	        .bind(cart_id).execute(pool).await?;
425	
426	    sqlx::query(
427	        "INSERT INTO order_verification_snapshots (cart_id, user_id, snapshot_json, expires_at)
428	         VALUES ($1,$2,$3,$4)",
429	    )
430	    .bind(cart_id).bind(p.user_id)
431	    .bind(snapshot_json).bind(expires_at)
432	    .execute(pool).await?;
433	
434	    Ok(summary)
435	}
