437	// ── confirm: transactional order creation --------------------------------
438	pub async fn confirm_order(pool: &PgPool, p: &Principal) -> Result<OrderDetail, ApiAppError> {
439	    p.require("orders:write")?;
440	    let cart_id = active_cart_id(pool, p.user_id).await?;
441	
442	    // Verify a fresh-enough snapshot exists
443	    let snapshot: Option<(Uuid, serde_json::Value)> = sqlx::query_as(
444	        "SELECT id, snapshot_json FROM order_verification_snapshots
445	         WHERE cart_id=$1 AND user_id=$2 AND expires_at > NOW()
446	         ORDER BY verified_at DESC LIMIT 1",
447	    )
448	    .bind(cart_id).bind(p.user_id).fetch_optional(pool).await?;
449	    let (_snap_id, snap_json) = snapshot.ok_or_else(|| {
450	        ApiAppError::BadRequest("cart not verified or snapshot expired — verify first".into())
451	    })?;
452	    let summary: PricingSummary = serde_json::from_value(snap_json)
453	        .map_err(|e| ApiAppError::Internal(e.to_string()))?;
454	
455	    let cart: (Option<Uuid>, Option<Uuid>) = sqlx::query_as(
456	        "SELECT coupon_id, delivery_method_id FROM carts WHERE id=$1",
457	    )
458	    .bind(cart_id).fetch_one(pool).await?;
459	    let delivery_method_id = cart.1.ok_or_else(|| {
460	        ApiAppError::BadRequest("delivery method not set".into())
461	    })?;
462	
463	    let mut tx = pool.begin().await?;
464	
465	    // Re-price inside the transaction to detect price changes since snapshot
466	    let lines_db: Vec<(Uuid, i32)> = sqlx::query_as(
467	        "SELECT product_id, quantity FROM cart_lines WHERE cart_id=$1 FOR UPDATE",
468	    )
469	    .bind(cart_id).fetch_all(&mut *tx).await?;
470	
471	    if lines_db.is_empty() {
472	        return Err(ApiAppError::BadRequest("cart is empty".into()));
473	    }
474	
475	    let delivery_fee: (i64,) = sqlx::query_as("SELECT fee_cents FROM delivery_methods WHERE id=$1")
476	        .bind(delivery_method_id).fetch_one(&mut *tx).await?;
477	
478	    let live_summary = price_cart(pool, &CartInput {
479	        lines: lines_db.clone(),
480	        coupon_id: cart.0,
481	        delivery_fee_cents: delivery_fee.0,
482	        user_roles: p.roles.clone(),
483	        user_id: p.user_id,
484	    }).await?;
485	
486	    // Price drift check
487	    if live_summary.total_cents != summary.total_cents {
488	        return Err(ApiAppError::BadRequest(format!(
489	            "prices changed since verification (was {}, now {}) — verify again",
490	            summary.total_cents, live_summary.total_cents
491	        )));
492	    }
493	
494	    // Stock check + deduct (with FOR UPDATE on each product row)
495	    for line in &live_summary.lines {
496	        let stock: (i32,) = sqlx::query_as(
497	            "SELECT stock FROM product_catalog WHERE id=$1 FOR UPDATE",
498	        )
499	        .bind(line.product_id).fetch_one(&mut *tx).await?;
500	        if stock.0 < line.quantity {
501	            return Err(ApiAppError::BadRequest(format!(
502	                "{}: stock dropped to {} since verification", line.name, stock.0
503	            )));
504	        }
505	        // Purchase limit check
506	        let existing: Option<(i32,)> = sqlx::query_as(
507	            "SELECT quantity FROM daily_purchase_tracking
508	             WHERE user_id=$1 AND product_id=$2 AND purchase_date=CURRENT_DATE FOR UPDATE",
509	        )
510	        .bind(p.user_id).bind(line.product_id).fetch_optional(&mut *tx).await?;
511	        let already = existing.map(|r| r.0).unwrap_or(0);
512	        if already + line.quantity > DAILY_LIMIT_PER_SKU {
513	            return Err(ApiAppError::BadRequest(format!(
514	                "{}: daily limit {} exceeded (already {}, requesting {})",
515	                line.name, DAILY_LIMIT_PER_SKU, already, line.quantity
516	            )));
517	        }
518	        // Deduct stock
519	        sqlx::query("UPDATE product_catalog SET stock = stock - $2 WHERE id=$1")
520	            .bind(line.product_id).bind(line.quantity)
521	            .execute(&mut *tx).await?;
522	        // Record daily purchase
523	        sqlx::query(
524	            "INSERT INTO daily_purchase_tracking (user_id, product_id, quantity)
525	             VALUES ($1,$2,$3)
526	             ON CONFLICT (user_id, product_id, purchase_date)
527	             DO UPDATE SET quantity = daily_purchase_tracking.quantity + EXCLUDED.quantity",
528	        )
529	        .bind(p.user_id).bind(line.product_id).bind(line.quantity)
530	        .execute(&mut *tx).await?;
531	    }
532	
533	    // Increment coupon usage
534	    if let Some(coupon_id) = cart.0 {
535	        if live_summary.coupon_applied {
536	            sqlx::query("UPDATE coupons SET times_used = times_used + 1 WHERE id=$1")
537	                .bind(coupon_id).execute(&mut *tx).await?;
538	        }
539	    }
540	
541	    // Build ref_code
542	    let count: (i64,) = sqlx::query_as("SELECT COUNT(*) FROM orders").fetch_one(&mut *tx).await?;
543	    let ref_code = format!("ORD-{:06}", count.0 + 1);
544	
545	    // Create order
546	    let order_id: (Uuid,) = sqlx::query_as(
547	        "INSERT INTO orders
548	           (ref_code, user_id, delivery_method_id, coupon_id, status,
549	            subtotal_cents, delivery_fee_cents, discount_cents, total_cents)
550	         VALUES ($1,$2,$3,$4,'confirmed',$5,$6,$7,$8) RETURNING id",
551	    )
552	    .bind(&ref_code)
553	    .bind(p.user_id)
554	    .bind(delivery_method_id)
555	    .bind(cart.0)
556	    .bind(live_summary.subtotal_cents)
557	    .bind(live_summary.delivery_fee_cents)
558	    .bind(live_summary.coupon_discount_cents)
559	    .bind(live_summary.total_cents)
560	    .fetch_one(&mut *tx).await?;
561	
562	    // Order lines
563	    for line in &live_summary.lines {
564	        sqlx::query(
565	            "INSERT INTO order_lines
566	               (order_id, product_id, quantity, unit_price_cents, line_total_cents,
567	                member_price_applied, threshold_discount_applied, discount_bps)
568	             VALUES ($1,$2,$3,$4,$5,$6,$7,$8)",
569	        )
570	        .bind(order_id.0)
571	        .bind(line.product_id)
572	        .bind(line.quantity)
573	        .bind(line.unit_price_cents)
574	        .bind(line.line_total_cents)
575	        .bind(line.member_price_applied)
576	        .bind(line.threshold_discount_applied)
577	        .bind(line.discount_bps)
578	        .execute(&mut *tx).await?;
579	    }
580	
581	    // Adjustments
582	    if live_summary.delivery_fee_cents > 0 {
583	        let dm_label: (String,) = sqlx::query_as("SELECT label FROM delivery_methods WHERE id=$1")
584	            .bind(delivery_method_id).fetch_one(&mut *tx).await?;
585	        sqlx::query(
586	            "INSERT INTO order_adjustments (order_id, kind, label, amount_cents) VALUES ($1,'delivery_fee',$2,$3)",
587	        )
588	        .bind(order_id.0).bind(dm_label.0).bind(live_summary.delivery_fee_cents)
589	        .execute(&mut *tx).await?;
590	    }
591	    if live_summary.coupon_discount_cents > 0 {
592	        let clabel = live_summary.coupon_code.as_deref().unwrap_or("coupon");
593	        sqlx::query(
594	            "INSERT INTO order_adjustments (order_id, kind, label, amount_cents) VALUES ($1,'coupon',$2,$3)",
595	        )
596	        .bind(order_id.0).bind(format!("Coupon {clabel}")).bind(-live_summary.coupon_discount_cents)
597	        .execute(&mut *tx).await?;
598	    }
599	
600	    // Deactivate cart + clear snapshot
601	    sqlx::query("UPDATE carts SET is_active=false, updated_at=NOW() WHERE id=$1")
602	        .bind(cart_id).execute(&mut *tx).await?;
603	    sqlx::query("DELETE FROM order_verification_snapshots WHERE cart_id=$1")
604	        .bind(cart_id).execute(&mut *tx).await?;
605	
606	    tx.commit().await?;
607	    load_order(pool, p, order_id.0).await
