5	#[derive(Debug, Error)]
6	pub enum ApiAppError {
7	    #[error("not found")]
8	    NotFound,
9	    #[error("bad request: {0}")]
10	    BadRequest(String),
11	    #[error("unauthorized: {0}")]
12	    Unauthorized(String),
13	    #[error("forbidden: {0}")]
14	    Forbidden(String),
15	    #[error("rate limited (retry after {0}s)")]
16	    RateLimited(u64),
17	    #[error("internal: {0}")]
18	    Internal(String),
19	}
20	
21	impl ResponseError for ApiAppError {
22	    fn status_code(&self) -> StatusCode {
23	        match self {
24	            Self::NotFound => StatusCode::NOT_FOUND,
25	            Self::BadRequest(_) => StatusCode::BAD_REQUEST,
26	            Self::Unauthorized(_) => StatusCode::UNAUTHORIZED,
27	            Self::Forbidden(_) => StatusCode::FORBIDDEN,
28	            Self::RateLimited(_) => StatusCode::TOO_MANY_REQUESTS,
29	            Self::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
30	        }
31	    }
32	
33	    fn error_response(&self) -> HttpResponse {
34	        let (code, message) = match self {
35	            Self::NotFound => ("not_found".into(), self.to_string()),
36	            Self::BadRequest(m) => ("bad_request".into(), m.clone()),
37	            Self::Unauthorized(m) => ("unauthorized".into(), m.clone()),
38	            Self::Forbidden(m) => ("forbidden".into(), m.clone()),
39	            Self::RateLimited(s) => ("rate_limited".into(), format!("retry after {s}s")),
40	            Self::Internal(m) => ("internal".into(), m.clone()),
41	        };
42	        let mut resp = HttpResponse::build(self.status_code());
43	        if let Self::RateLimited(s) = self {
44	            resp.insert_header(("Retry-After", s.to_string()));
45	        }
46	        resp.json(ApiError { code, message })
47	    }
48	}
49	
50	impl From<sqlx::Error> for ApiAppError {
51	    fn from(e: sqlx::Error) -> Self {
52	        ApiAppError::Internal(e.to_string())
53	    }
54	}
55	
56	impl From<anyhow::Error> for ApiAppError {
57	    fn from(e: anyhow::Error) -> Self {
58	        ApiAppError::Internal(e.to_string())
