//! Domain crate — pure business types and rules.
//!
//! Phase 1: only baseline identity/organisation entities are modelled.
//! Business modules (requisitions, orders, inventory, etc.) are introduced
//! in later phases and must live here, not in infrastructure.

pub mod identity;
pub mod organisation;

use thiserror::Error;

#[derive(Debug, Error)]
pub enum DomainError {
    #[error("invariant violated: {0}")]
    Invariant(String),
}
---
//! Application crate — orchestrates use cases over domain ports.
//!
//! Phase 1 only declares the port traits the infrastructure crate will
//! implement. Use-case structs are added in later phases as the business
//! modules come online.

use async_trait::async_trait;
use domain::identity::User;
use thiserror::Error;
use uuid::Uuid;

#[derive(Debug, Error)]
pub enum AppError {
    #[error("not found")]
    NotFound,
    #[error("repository error: {0}")]
    Repository(String),
}

pub type AppResult<T> = Result<T, AppError>;

#[async_trait]
pub trait UserRepository: Send + Sync {
    async fn find_by_id(&self, id: Uuid) -> AppResult<Option<User>>;
}
