110	// ---------------------------------------------------------------------------
111	// Public API
112	// ---------------------------------------------------------------------------
113	
114	/// Encrypts `plaintext` with AES-256-GCM using a freshly generated 12-byte
115	/// (96-bit) nonce.
116	///
117	/// Returns `base64(nonce):base64(ciphertext)`.
118	///
119	/// # Security
120	/// NEVER log the plaintext argument; log only lengths or error kinds.
121	pub fn encrypt(plaintext: &str) -> Result<String, CryptoError> {
122	    let cipher = cipher()?;
123	
124	    // Generate a random 12-byte nonce (96 bits — standard for GCM).
125	    let mut nonce_bytes = [0u8; 12];
126	    OsRng.fill_bytes(&mut nonce_bytes);
127	    let nonce = Nonce::from_slice(&nonce_bytes);
128	
129	    let ciphertext = cipher
130	        .encrypt(nonce, plaintext.as_bytes())
131	        .map_err(|e| CryptoError::Aead(e.to_string()))?;
132	
133	    let encoded = format!("{}:{}", B64.encode(nonce_bytes), B64.encode(&ciphertext));
134	    Ok(encoded)
135	}
136	
137	/// Decrypts a value produced by [`encrypt`].
138	///
139	/// Expects the format `base64(nonce):base64(ciphertext)`.
140	///
141	/// # Security
142	/// NEVER log the returned plaintext; log only lengths or error kinds.
143	pub fn decrypt(ciphertext: &str) -> Result<String, CryptoError> {
144	    let cipher = cipher()?;
145	
146	    let (nonce_b64, ct_b64) = ciphertext
147	        .split_once(':')
148	        .ok_or(CryptoError::InvalidFormat)?;
149	
150	    let nonce_bytes = B64.decode(nonce_b64)?;
151	    if nonce_bytes.len() != 12 {
152	        return Err(CryptoError::InvalidFormat);
153	    }
154	    let nonce = Nonce::from_slice(&nonce_bytes);
155	
156	    let ct_bytes = B64.decode(ct_b64)?;
157	
158	    let plaintext_bytes = cipher
159	        .decrypt(nonce, ct_bytes.as_slice())
160	        .map_err(|e| CryptoError::Aead(e.to_string()))?;
161	
162	    String::from_utf8(plaintext_bytes)
163	        .map_err(|e| CryptoError::Aead(format!("UTF-8 decode failed: {e}")))
164	}
